type Key =
  | Digit(d: Int)
  | Enter
  | Clear

fn door_lock(code: String, events: List[Key]) -> String {
  let capacity = str_len(code)
  var state = "locked"
  var buffer = take([""], 0)
  var failures = 0
  for key in events {
    if state == "locked" {
      if key == Enter {
        if join(buffer, "") == code {
          state = "open"
          failures = 0
        } else {
          failures = failures + 1
          if failures == 3 {
            return "blocked"
          }
        }
      }
      let excess = max(0, len(buffer) + 1 - capacity)
      buffer = match key {
        Digit(d) => append(drop(buffer, excess), to_string(d)),
        _ => [],
      }
    } else if key == Enter {
      state = "locked"
    }
  }
  return state
}

