type BankOp =
  | Open(name: String)
  | Deposit(name: String, amount: Int)
  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

fn open_account(accounts: Map[String, Int], name: String) -> Result[Map[String, Int], String] {
  return match map_get(accounts, name) {
    Some(_) => Err("duplicate account " + name),
    None => Ok(map_set(accounts, name, 0)),
  }
}

fn account_balance(accounts: Map[String, Int], name: String) -> Result[Int, String] {
  return match map_get(accounts, name) {
    Some(balance) => Ok(balance),
    None => Err("unknown account " + name),
  }
}

fn deposit(
  accounts: Map[String, Int],
  name: String,
  amount: Int,
) -> Result[Map[String, Int], String] {
  let balance = try account_balance(accounts, name)
  if amount <= 0 {
    return Err("invalid amount")
  }
  return Ok(map_set(accounts, name, balance + amount))
}

fn withdraw(
  accounts: Map[String, Int],
  name: String,
  amount: Int,
) -> Result[Map[String, Int], String] {
  let balance = try account_balance(accounts, name)
  if amount <= 0 {
    return Err("invalid amount")
  }
  if amount > balance {
    return Err("insufficient funds")
  }
  return Ok(map_set(accounts, name, balance - amount))
}

fn transfer(
  accounts: Map[String, Int],
  src: String,
  dst: String,
  amount: Int,
) -> Result[Map[String, Int], String] {
  let src_balance = try account_balance(accounts, src)
  let dst_balance = try account_balance(accounts, dst)
  if src == dst {
    return Err("same account")
  }
  if amount <= 0 {
    return Err("invalid amount")
  }
  if amount > src_balance {
    return Err("insufficient funds")
  }
  let debited = map_set(accounts, src, src_balance - amount)
  return Ok(map_set(debited, dst, dst_balance + amount))
}

fn apply_op(
  accounts: Map[String, Int],
  op: BankOp,
  step: Int,
) -> Result[Map[String, Int], String] {
  let outcome = match op {
    Open(name) => open_account(accounts, name),
    Deposit(name, amount) => deposit(accounts, name, amount),
    Withdraw(name, amount) => withdraw(accounts, name, amount),
    Transfer(src, dst, amount) => transfer(accounts, src, dst, amount),
  }
  return match outcome {
    Ok(updated) => Ok(updated),
    Err(message) => Err("step " + to_string(step) + ": " + message),
  }
}

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var accounts = map_from([])
  for (i, op) in enumerate(ops) {
    accounts = try apply_op(accounts, op, i + 1)
  }
  let entries = zip(keys(accounts), values(accounts))
  return Ok(entries)
}

