fn next_permutation(xs: List[Int]) -> List[Int] {
  var pivot_at = -1
  var pivot = 0
  var previous = 0
  for (i, x) in enumerate(xs) {
    if i > 0 && previous < x {
      pivot_at = i - 1
      pivot = previous
    }
    previous = x
  }
  if pivot_at == -1 {
    return reverse(xs)
  }

  let suffix = reverse(drop(xs, pivot_at + 1))
  var successor_at = 0
  var successor = pivot
  for (i, x) in enumerate(suffix) {
    if x > pivot {
      successor_at = i
      successor = x
      break
    }
  }

  var out = append(take(xs, pivot_at), successor)
  for (i, x) in enumerate(suffix) {
    if i == successor_at {
      out = append(out, pivot)
    } else {
      out = append(out, x)
    }
  }
  return out
}

