fn component_root(parents: Map[Int, Int], index: Int) -> Int {
  var root = index
  var parent = unwrap_or(map_get(parents, root), -1)
  while parent >= 0 {
    root = parent
    parent = unwrap_or(map_get(parents, root), -1)
  }
  return root
}

