  let a_root = component_root(parents, a)
  let b_root = component_root(parents, b)
  if a_root == b_root {
    return parents
  }
  # A root stores the negative of its component size.
  let a_size = unwrap_or(map_get(parents, a_root), -1)
  let b_size = unwrap_or(map_get(parents, b_root), -1)
  if a_size <= b_size {
    return map_set(map_set(parents, b_root, a_root), a_root, a_size + b_size)
  }
  return map_set(map_set(parents, a_root, b_root), b_root, a_size + b_size)
}

