type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

fn create_order(orders: Map[String, String], id: String) -> Result[Map[String, String], String] {
  return match map_get(orders, id) {
    Some(_) => Err("duplicate order: " + id),
    None => Ok(map_set(orders, id, "created")),
  }
}

fn change_order(
  orders: Map[String, String],
  id: String,
  verb: String,
  allowed: List[String],
  next_state: String,
) -> Result[Map[String, String], String] {
  let state = match map_get(orders, id) {
    Some(current) => Ok(current),
    None => Err("unknown order: " + id),
  }
  let current = try state
  if !contains(allowed, current) {
    return Err("cannot " + verb + " " + id + " from " + current)
  }
  return Ok(map_set(orders, id, next_state))
}

fn apply_event(
  orders: Map[String, String],
  event: OrderEvent,
) -> Result[Map[String, String], String] {
  return match event {
    Create(id) => create_order(orders, id),
    Pay(id) => change_order(orders, id, "pay", ["created"], "paid"),
    Ship(id) => change_order(orders, id, "ship", ["paid"], "shipped"),
    Cancel(id) => change_order(orders, id, "cancel", ["created", "paid"], "cancelled"),
  }
}

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var orders = map_from(take([("", "")], 0))
  for event in events {
    orders = try apply_event(orders, event)
  }
  let pairs = zip(keys(orders), values(orders))
  let sorted = sort_by(pairs, |pair| pair.0)
  return Ok(sorted)
}

