  for ch in split(s, "") {
    if ch != "" {
      if ch == previous {
        count = count + 1
      } else {
        encoded = encoded + rle_run(previous, count)
        previous = ch
        count = 1
      }
    }
  }
  encoded = encoded + rle_run(previous, count)
  if str_len(encoded) < str_len(s) {
    return encoded
  }
  return s
}

