type Event =
  | Coin(cents: Int)
  | Select(price: Int)
  | Refund

fn accept_coin(credit: Int, messages: List[String], cents: Int) -> (Int, List[String]) {
  if cents == 5 || cents == 10 || cents == 25 || cents == 100 {
    return (credit + cents, messages)
  }
  return (credit, append(messages, "reject " + to_string(cents)))
}

fn select_item(credit: Int, messages: List[String], price: Int) -> (Int, List[String]) {
  if credit >= price {
    let message = "vend " + to_string(price) + " change " + to_string(credit - price)
    return (0, append(messages, message))
  }
  return (credit, append(messages, "insufficient " + to_string(credit)))
}

fn refund_credit(credit: Int, messages: List[String]) -> List[String] {
  if credit > 0 {
    return append(messages, "refund " + to_string(credit))
  }
  return messages
}

fn vending_machine(events: List[Event]) -> List[String] {
  var credit = 0
  var messages = take([""], 0)
  for event in events {
    let next = match event {
      Coin(cents) => accept_coin(credit, messages, cents),
      Select(price) => select_item(credit, messages, price),
      Refund => (0, refund_credit(credit, messages)),
    }
    credit = next.0
    messages = next.1
  }
  return refund_credit(credit, messages)
}

