fn tic_tac_toe(board: List[String]) -> String {
  var xs = []
  var os = []
  for (row_index, row) in enumerate(board) {
    let cells = filter(split(row, ""), |cell| cell != "")
    for (col_index, cell) in enumerate(cells) {
      let position = row_index * 3 + col_index
      if cell == "X" {
        xs = append(xs, position)
      } else if cell == "O" {
        os = append(os, position)
      }
    }
  }

  let x_count = len(xs)
  let o_count = len(os)
  let difference = x_count - o_count
  if difference != 0 && difference != 1 {
    return "invalid"
  }

  let x_wins = has_line(xs)
  let o_wins = has_line(os)
  if x_wins && o_wins {
    return "invalid"
  }
  if x_wins {
    if difference != 1 {
      return "invalid"
    }
    return "X wins"
  }
  if o_wins {
    if difference != 0 {
      return "invalid"
    }
    return "O wins"
  }
  if x_count + o_count == 9 {
    return "draw"
  }
  return "in progress"
}

