def glob_match(pattern: str, s: str) -> bool:
    p = 0
    i = 0
    after_star = -1
    star_end = 0

    while i < len(s):
        if p < len(pattern):
            char = pattern[p]
            if char == "*":
                p += 1
                after_star = p
                star_end = i
                continue

            width = 1
            if char == "\\":
                if p + 1 < len(pattern):
                    char = pattern[p + 1]
                    width = 2
                matched = char == s[i]
            else:
                matched = char == "?" or char == s[i]

            if matched:
                p += width
                i += 1
                continue

        if after_star == -1:
            return False

        star_end += 1
        i = star_end
        p = after_star

    while p < len(pattern) and pattern[p] == "*":
        p += 1
    return p == len(pattern)

