def _translate_word(word: str) -> str:
    for index, letter in enumerate(word):
        if letter == "y":
            is_vowel = index > 0
        elif letter == "u":
            is_vowel = index == 0 or word[index - 1] != "q"
        else:
            is_vowel = letter in "aeio"

        if is_vowel:
            if index == 0:
                return word + "way"
            return word[index:] + word[:index] + "ay"

    return word + "ay"


