from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

class Forward(TypedDict):
    kind: Literal["Forward"]
    steps: int

class TurnLeft(TypedDict):
    kind: Literal["TurnLeft"]

class TurnRight(TypedDict):
    kind: Literal["TurnRight"]

Cmd = Forward | TurnLeft | TurnRight


def robot_walk(
    cmds: list[Cmd], obstacles: list[tuple[int, int]]
) -> tuple[int, int, str]:
    blocked = set(obstacles)
    directions = ("N", "E", "S", "W")
    offsets = ((0, 1), (1, 0), (0, -1), (-1, 0))
    x, y = 0, 0
    heading = 0

    for cmd in cmds:
        if cmd["kind"] == "Forward":
            dx, dy = offsets[heading]
            for _ in range(cmd["steps"]):
                next_cell = (x + dx, y + dy)
                if next_cell in blocked:
                    break
                x, y = next_cell
        elif cmd["kind"] == "TurnLeft":
            heading = (heading - 1) % 4
        else:
            heading = (heading + 1) % 4

    return x, y, directions[heading]

