def wrap_text(s: str, width: int) -> list[str]:
    lines: list[str] = []
    current: list[str] = []
    length = 0

    for word in s.split(" "):
        if not word:
            continue

        word_length = len(word)
        if current and length + 1 + word_length > width:
            lines.append(" ".join(current))
            current = []
            length = 0

        if current:
            length += 1
        current.append(word)
        length += word_length

    if current:
        lines.append(" ".join(current))

    return lines

