export function anagram_groups(words: string[]): string[][] {
  const groups = new Map<string, string[]>();

  for (const word of words) {
    const key = JSON.stringify(Array.from(word).sort());
    const group = groups.get(key);

    if (group === undefined) {
      groups.set(key, [word]);
    } else {
      group.push(word);
    }
  }

  return Array.from(groups.values()).filter((group) => group.length >= 2);
}

