type Person = { name: string; age: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function age_histogram(
  people: Person[],
  width: number,
): Result<([string, number])[]> {
  if (width < 1) {
    return { ok: false, error: "bad width" };
  }

  for (const person of people) {
    if (person.age < 0) {
      return { ok: false, error: `negative age: ${person.name}` };
    }
  }

  const counts = new Map<number, number>();
  let lowest = Infinity;
  let highest = -Infinity;

  for (const person of people) {
    const bucket = Math.floor(person.age / width);
    counts.set(bucket, (counts.get(bucket) ?? 0) + 1);
    lowest = Math.min(lowest, bucket);
    highest = Math.max(highest, bucket);
  }

  const value: [string, number][] = [];
  for (let bucket = lowest; bucket <= highest; bucket += 1) {
    const start = bucket * width;
    const end = start + width - 1;
    value.push([`${start}-${end}`, counts.get(bucket) ?? 0]);
    if (bucket === highest) {
      break;
    }
  }

  return { ok: true, value };
}

