export function caesar_shift(s: string, k: number): string {
  const shift = ((k % 26) + 26) % 26;
  return s.replace(/[a-z]/g, (letter) =>
    String.fromCharCode(97 + ((letter.charCodeAt(0) - 97 + shift) % 26)),
  );
}

