type BankOp =
  | { kind: "Open"; name: string }
  | { kind: "Deposit"; name: string; amount: number }
  | { kind: "Withdraw"; name: string; amount: number }
  | { kind: "Transfer"; src: string; dst: string; amount: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bank_ledger(ops: BankOp[]): Result<([string, number])[]> {
  const balances = new Map<string, number>();

  for (const [index, op] of ops.entries()) {
    const fail = (message: string): { ok: false; error: string } => ({
      ok: false,
      error: `step ${index + 1}: ${message}`,
    });

    if (op.kind === "Open") {
      if (balances.has(op.name)) return fail(`duplicate account ${op.name}`);
      balances.set(op.name, 0);
      continue;
    }

    const name = op.kind === "Transfer" ? op.src : op.name;
    const balance = balances.get(name);
    if (balance === undefined) return fail(`unknown account ${name}`);

    if (op.kind === "Transfer") {
      const destinationBalance = balances.get(op.dst);
      if (destinationBalance === undefined) return fail(`unknown account ${op.dst}`);
      if (op.src === op.dst) return fail("same account");
      if (op.amount <= 0) return fail("invalid amount");
      if (op.amount > balance) return fail("insufficient funds");

      balances.set(op.src, balance - op.amount);
      balances.set(op.dst, destinationBalance + op.amount);
    } else {
      if (op.amount <= 0) return fail("invalid amount");

      if (op.kind === "Withdraw") {
        if (op.amount > balance) return fail("insufficient funds");
        balances.set(name, balance - op.amount);
      } else {
        balances.set(name, balance + op.amount);
      }
    }
  }

  return { ok: true, value: Array.from(balances.entries()) };
}

