type Shift = { worker: string; start_hour: number; end_hour: number };

export function coverage_gaps(shifts: Shift[], required: number): number[] {
  const gaps: number[] = [];

  for (let hour = 0; hour < 24; hour++) {
    const workers = new Set<string>();

    for (const shift of shifts) {
      if (shift.start_hour <= hour && hour < shift.end_hour) {
        workers.add(shift.worker);
      }
    }

    if (workers.size < required) {
      gaps.push(hour);
    }
  }

  return gaps;
}

