type Player = { name: string; score: number };

function compareNames(a: string, b: string): number {
  const right = b[Symbol.iterator]();

  for (const char of a) {
    const next = right.next();
    if (next.done) return 1;

    const difference = char.codePointAt(0)! - next.value.codePointAt(0)!;
    if (difference !== 0) return difference;
  }

  return right.next().done ? 0 : -1;
}

export function competition_rank(players: Player[]): ([number, string])[] {
  const sorted = [...players].sort((a, b) => {
    if (a.score > b.score) return -1;
    if (a.score < b.score) return 1;
    return compareNames(a.name, b.name);
  });

  let rank = 0;
  return sorted.map((player, index): [number, string] => {
    if (index === 0 || player.score !== sorted[index - 1].score) {
      rank = index + 1;
    }
    return [rank, player.name];
  });
}

