type Key = { kind: "Digit"; d: number } | { kind: "Enter" } | { kind: "Clear" };

export function door_lock(code: string, events: Key[]): string {
  let state: "locked" | "open" = "locked";
  let buffer = "";
  let failures = 0;

  for (const event of events) {
    if (state === "open") {
      if (event.kind === "Enter") {
        state = "locked";
      }
      continue;
    }

    switch (event.kind) {
      case "Digit":
        buffer = (buffer + String(event.d)).slice(-code.length);
        break;
      case "Clear":
        buffer = "";
        break;
      case "Enter": {
        const matches = buffer === code;
        buffer = "";
        if (matches) {
          state = "open";
          failures = 0;
        } else {
          failures += 1;
          if (failures === 3) {
            return "blocked";
          }
        }
        break;
      }
    }
  }

  return state;
}

