  const left = parseVersion(a);
  if (left === null) return { ok: false, error: "bad version: " + a };

  const right = parseVersion(b);
  if (right === null) return { ok: false, error: "bad version: " + b };

  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const x = left[i] ?? "";
    const y = right[i] ?? "";

    if (x.length !== y.length) {
