export function count_islands(grid: string[]): [number, number] {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  if (width === 0) return [0, 0];

  const visited = new Uint8Array(height * width);
  const stack: number[] = [];
  let islands = 0;
  let largest = 0;

  function visit(row: number, col: number): void {
    const index = row * width + col;
    if (visited[index] !== 0 || grid[row][col] !== "#") return;
    visited[index] = 1;
    stack.push(index);
  }

  for (let row = 0; row < height; row++) {
    for (let col = 0; col < width; col++) {
      visit(row, col);
      if (stack.length === 0) continue;

      islands++;
      let size = 0;
      for (let index = stack.pop(); index !== undefined; index = stack.pop()) {
        size++;
        const r = Math.floor(index / width);
        const c = index % width;
        if (r > 0) visit(r - 1, c);
        if (r + 1 < height) visit(r + 1, c);
        if (c > 0) visit(r, c - 1);
        if (c + 1 < width) visit(r, c + 1);
      }
      largest = Math.max(largest, size);
    }
  }

  return [islands, largest];
}

