type Job = { name: string; deps: string[] };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function build_order(jobs: Job[]): Result<string[]> {
  const indexByName = new Map<string, number>();
  for (let i = 0; i < jobs.length; i++) {
    const name = jobs[i].name;
    if (indexByName.has(name)) {
      return { ok: false, error: "duplicate job: " + name };
    }
    indexByName.set(name, i);
  }

  const remaining = jobs.map(job => job.deps.length);
  const dependents = jobs.map((): number[] => []);
  for (let i = 0; i < jobs.length; i++) {
    for (const name of jobs[i].deps) {
      const dependency = indexByName.get(name);
      if (dependency === undefined) {
        return { ok: false, error: "unknown dependency: " + name };
      }
      dependents[dependency].push(i);
    }
  }

  // Keep ready jobs in a min-heap keyed by input index.
  const ready: number[] = [];

  function enqueue(index: number): void {
    let position = ready.length;
    ready.push(index);
    while (position > 0) {
      const parent = Math.floor((position - 1) / 2);
      if (ready[parent] <= index) break;
      ready[position] = ready[parent];
      position = parent;
    }
    ready[position] = index;
  }

  function dequeue(): number | undefined {
    const first = ready[0];
    const last = ready.pop();
    if (last === undefined || ready.length === 0) return first;

    let position = 0;
    while (2 * position + 1 < ready.length) {
      let child = 2 * position + 1;
      const right = child + 1;
      if (right < ready.length && ready[right] < ready[child]) {
        child = right;
      }
      if (last <= ready[child]) break;
      ready[position] = ready[child];
      position = child;
    }
    ready[position] = last;
    return first;
  }

  for (let i = 0; i < jobs.length; i++) {
    if (remaining[i] === 0) enqueue(i);
  }

  const order: string[] = [];
  while (order.length < jobs.length) {
    const index = dequeue();
    if (index === undefined) {
      return { ok: false, error: "cycle detected" };
    }
    order.push(jobs[index].name);
    for (const dependent of dependents[index]) {
      remaining[dependent]--;
      if (remaining[dependent] === 0) enqueue(dependent);
    }
  }
  return { ok: true, value: order };
}

