type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bowling_score(rolls: number[]): Result<number> {
  for (const roll of rolls) {
    if (roll < 0 || roll > 10) {
      return { ok: false, error: "invalid roll" };
    }
  }

  const frameStarts: number[] = [];
  let index = 0;

  for (let frame = 1; frame <= 9; frame++) {
    frameStarts.push(index);

    const first = rolls[index++];
    if (first === undefined) {
      return { ok: false, error: "incomplete game" };
    }
    if (first === 10) {
      continue;
    }

    const second = rolls[index++];
    if (second === undefined) {
      return { ok: false, error: "incomplete game" };
    }
    if (first + second > 10) {
      return { ok: false, error: `too many pins in frame ${frame}` };
    }
  }

  const first = rolls[index++];
  const second = rolls[index++];
  if (first === undefined || second === undefined) {
    return { ok: false, error: "incomplete game" };
  }

  let score = first + second;
  if (first !== 10 && score > 10) {
    return { ok: false, error: "too many pins in frame 10" };
  }

  if (first === 10 || score === 10) {
    const third = rolls[index++];
    if (third === undefined) {
      return { ok: false, error: "incomplete game" };
    }
    if (first === 10 && second !== 10 && second + third > 10) {
      return { ok: false, error: "too many pins in frame 10" };
    }
    score += third;
  }

  if (index < rolls.length) {
    return { ok: false, error: "too many rolls" };
  }

  for (const start of frameStarts) {
    const pins = rolls[start] + rolls[start + 1];
    score += pins;
    if (rolls[start] === 10 || pins === 10) {
      score += rolls[start + 2];
    }
  }

  return { ok: true, value: score };
}

