export function find_all(s: string, pat: string): number[] {
  const positions: number[] = [];
  if (pat.length === 0) {
    return positions;
  }

  let start = 0;
  while (true) {
    const match = s.indexOf(pat, start);
    if (match === -1) {
      return positions;
    }
    positions.push(match);
    start = match + 1;
  }
}

