  const target = Array.from(b);

  let twoBack = new Array<number>(target.length + 1).fill(0);
  let previous = Array.from({ length: target.length + 1 }, (_, j) => j);
  let current = new Array<number>(target.length + 1).fill(0);

  for (let i = 1; i <= source.length; i++) {
    current[0] = i;

    for (let j = 1; j <= target.length; j++) {
      const replacementCost = source[i - 1] === target[j - 1] ? 0 : 1;
      let best = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + replacementCost,
      );

      if (
        i >= 2 &&
        j >= 2 &&
        source[i - 1] === target[j - 2] &&
        source[i - 2] === target[j - 1]
      ) {
        best = Math.min(best, twoBack[j - 2] + 1);
      }

      current[j] = best;
    }

    const reusable = twoBack;
    twoBack = previous;
    previous = current;
    current = reusable;
  }

  return previous[target.length];
}

