type Meeting = { start: number; end: number };

export function free_slots(
  meetings: Meeting[],
  day_start: number,
  day_end: number,
): ([number, number])[] {
  if (day_end <= day_start) return [];

  const occupied: Meeting[] = [];
  for (const meeting of meetings) {
    const start = Math.max(day_start, meeting.start);
    const end = Math.min(day_end, meeting.end);
    if (start < end) occupied.push({ start, end });
  }
  occupied.sort((a, b) => a.start - b.start);

  const free: [number, number][] = [];
  let cursor = day_start;
  for (const { start, end } of occupied) {
    if (start > cursor) free.push([cursor, start]);
    cursor = Math.max(cursor, end);
  }
  if (cursor < day_end) free.push([cursor, day_end]);

  return free;
}

