export function heading_numbers(lines: string[]): string[] {
  const counters = [0, 0, 0];
  const output: string[] = [];

  for (const line of lines) {
    const marker = /^#{1,3} /.exec(line);
    if (marker === null || marker[0].length === line.length) {
      continue;
    }

    const titleStart = marker[0].length;
    const level = titleStart - 1;
    counters[level - 1] += 1;
    counters.fill(0, level);

    output.push(`${counters.slice(0, level).join(".")} ${line.slice(titleStart)}`);
  }

  return output;
}

