export function glob_match(pattern: string, s: string): boolean {
  const tokens = Array.from(pattern);
  const chars = Array.from(s);
  const matches = new Array<boolean>(chars.length + 1).fill(false);
  matches[0] = true;

  for (let i = 0; i < tokens.length; i++) {
    let token = tokens[i];
    const escaped = token === "\\";
    if (escaped && i + 1 < tokens.length) {
      token = tokens[++i];
    }

    if (!escaped && token === "*") {
      for (let j = 1; j <= chars.length; j++) {
        matches[j] = matches[j] || matches[j - 1];
      }
    } else {
      const wildcard = !escaped && token === "?";
      for (let j = chars.length; j > 0; j--) {
        matches[j] = matches[j - 1] && (wildcard || token === chars[j - 1]);
      }
      matches[0] = false;
    }
  }

  return matches[chars.length];
}

