type Request = { endpoint: string; ms: number; status: number };

export function latency_report(entries: Request[]): [string, number, number, number][] {
  const groups = new Map<string, { times: number[]; errors: number }>();

  for (const { endpoint, ms, status } of entries) {
    let group = groups.get(endpoint);
    if (group === undefined) {
      group = { times: [], errors: 0 };
      groups.set(endpoint, group);
    }

    group.times.push(ms);
    if (status >= 500) {
      group.errors += 1;
    }
  }

  const report: [string, number, number, number][] = [];
  for (const [endpoint, { times, errors }] of groups) {
    times.sort((a, b) => a - b);
    const count = times.length;
    const rank = Math.floor((9 * count + 9) / 10);
    report.push([endpoint, count, times[rank - 1], errors]);
  }

  return report;
}

