type Line = { sku: string; qty: number; unit_cents: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function floor_div(value: bigint, divisor: bigint): bigint {
    const quotient = value / divisor;
    return value % divisor < 0n ? quotient - 1n : quotient;
}

export function invoice_total(lines: Line[], coupon: string): Result<number> {
    for (const line of lines) {
        if (line.qty < 1) {
            return { ok: false, error: "bad quantity: " + line.sku };
        }
    }

    let subtotal = 0n;
    for (const line of lines) {
        let amount = BigInt(line.qty) * BigInt(line.unit_cents);
        if (line.qty >= 10) {
            amount -= floor_div(amount, 10n);
        }
        subtotal += amount;
    }

    let amount = subtotal;
    switch (coupon) {
        case "":
            break;
        case "SAVE500":
            amount = subtotal >= 500n ? subtotal - 500n : 0n;
            break;
        case "PCT10":
            amount -= floor_div(subtotal, 10n);
            break;
        case "BIG20":
            if (subtotal < 10000n) {
                return { ok: false, error: "coupon not applicable: BIG20" };
            }
            amount -= floor_div(subtotal, 5n);
            break;
        default:
            return { ok: false, error: "unknown coupon: " + coupon };
    }

    const tax = floor_div(amount * 8n + 50n, 100n);
    return { ok: true, value: Number(amount + tax) };
}

