type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function isDigit(text: string, index: number): boolean {
  const code = text.charCodeAt(index);
  return code >= 48 && code <= 57;
}

export function flatten_nested(s: string): Result<[number[], number]> {
  const text = s.replace(/ /g, "");
  const invalid = (index: number): Result<[number[], number]> => ({
    ok: false,
    error: `invalid at ${index}`,
  });

  if (text[0] !== "[") return invalid(0);

  const values: number[] = [];
  let depth = 1;
  let maxDepth = 1;
  let i = 1;
  let state: "first" | "element" | "separator" = "first";

  while (i < text.length) {
    const char = text[i];

    if (char === "]" && state !== "element") {
      i++;
      depth--;
      if (depth === 0) {
        if (i !== text.length) return invalid(i);
        return { ok: true, value: [values, maxDepth] };
      }
      state = "separator";
    } else if (state === "separator") {
      if (char !== ",") return invalid(i);
      i++;
      state = "element";
    } else if (char === "[") {
      i++;
      depth++;
      maxDepth = Math.max(maxDepth, depth);
      state = "first";
    } else {
      const start = i;
      if (char === "-") i++;
      if (!isDigit(text, i)) return invalid(i);
      do {
        i++;
      } while (isDigit(text, i));
      values.push(Number(text.slice(start, i)));
      state = "separator";
    }
  }

  return invalid(text.length);
}

