export function max_subarray(xs: number[]): [number, number, number] | null {
  if (xs.length === 0) {
    return null;
  }

  let currentSum = xs[0];
  let currentStart = 0;
  let bestSum = currentSum;
  let bestStart = 0;
  let bestEnd = 0;

  for (let end = 1; end < xs.length; end++) {
    const value = xs[end];
    const extendedSum = currentSum + value;

    if (value > extendedSum) {
      currentSum = value;
      currentStart = end;
    } else {
      currentSum = extendedSum;
    }

    if (
      currentSum > bestSum ||
      (currentSum === bestSum && currentStart < bestStart)
    ) {
      bestSum = currentSum;
      bestStart = currentStart;
      bestEnd = end;
    }
  }

  return [bestSum, bestStart, bestEnd];
}

