export function next_permutation(xs: number[]): number[] {
  if (xs.length < 2) return xs;

  const result = xs.slice();
  let pivot = result.length - 2;
  while (pivot >= 0 && result[pivot] >= result[pivot + 1]) {
    pivot--;
  }

  if (pivot >= 0) {
    let successor = result.length - 1;
    while (result[successor] <= result[pivot]) {
      successor--;
    }
    [result[pivot], result[successor]] = [result[successor], result[pivot]];
  }

  for (let left = pivot + 1, right = result.length - 1; left < right; left++, right--) {
    [result[left], result[right]] = [result[right], result[left]];
  }

  return result;
}

