type Match = { home: string; away: string; home_goals: number; away_goals: number };

type Totals = { points: number; goalsFor: number; goalsAgainst: number };
type Row = [string, number, number, number];

function compareNames(a: string, b: string): number {
  const right = b[Symbol.iterator]();
  for (const left of a) {
    const next = right.next();
    if (next.done) return 1;
    const difference = left.codePointAt(0)! - next.value.codePointAt(0)!;
    if (difference !== 0) return difference;
  }
  return right.next().done ? 0 : -1;
}

export function league_table(matches: Match[]): ([string, number, number, number])[] {
  const teams = new Map<string, Totals>();

  function record(team: string, scored: number, conceded: number): void {
    let totals = teams.get(team);
    if (totals === undefined) {
      totals = { points: 0, goalsFor: 0, goalsAgainst: 0 };
      teams.set(team, totals);
    }
    totals.points += scored > conceded ? 3 : scored === conceded ? 1 : 0;
    totals.goalsFor += scored;
    totals.goalsAgainst += conceded;
  }

  for (const { home, away, home_goals, away_goals } of matches) {
    record(home, home_goals, away_goals);
    record(away, away_goals, home_goals);
  }

  const rows: Row[] = [];
  for (const [team, { points, goalsFor, goalsAgainst }] of teams) {
    rows.push([team, points, goalsFor - goalsAgainst, goalsFor]);
  }

  return rows.sort(
    (a, b) => b[1] - a[1] || b[2] - a[2] || b[3] - a[3] || compareNames(a[0], b[0]),
  );
}

