type Result<T> = { ok: true; value: T } | { ok: false; error: string };

type Operator = "+" | "-" | "*" | "/";

function precedence(op: Operator): number {
  return op === "*" || op === "/" ? 2 : 1;
}

export function eval_expr(s: string): Result<number> {
  const text = s.replaceAll(" ", "");
  const postfix: string[] = [];
  const operators: (Operator | "(")[] = [];
  let needOperand = true;
  let depth = 0;
  let i = 0;

  function unexpectedCharacter(): Result<number> {
    const character = String.fromCodePoint(text.codePointAt(i)!);
    return { ok: false, error: "unexpected character: " + character };
  }

  while (i < text.length) {
    const ch = text[i];

    if (needOperand) {
      if (ch === "(") {
        operators.push(ch);
        depth++;
        i++;
      } else if (ch >= "0" && ch <= "9") {
        const start = i;
        do {
          i++;
        } while (i < text.length && text[i] >= "0" && text[i] <= "9");
        postfix.push(text.slice(start, i));
        needOperand = false;
      } else {
        return unexpectedCharacter();
      }
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/") {
      while (operators.length > 0) {
        const top = operators[operators.length - 1];
        if (top === "(" || precedence(top) < precedence(ch)) break;
        postfix.push(operators.pop()!);
      }
      operators.push(ch);
      needOperand = true;
      i++;
    } else if (ch === ")" && depth > 0) {
      let top = operators.pop()!;
      while (top !== "(") {
        postfix.push(top);
        top = operators.pop()!;
      }
      depth--;
      i++;
    } else {
      return unexpectedCharacter();
    }
  }

  if (needOperand || depth !== 0) {
    return { ok: false, error: "unexpected end" };
  }

  while (operators.length > 0) {
    postfix.push(operators.pop()!);
  }

  const values: bigint[] = [];
  for (const token of postfix) {
    if (token === "+" || token === "-" || token === "*" || token === "/") {
      const right = values.pop()!;
      const left = values.pop()!;
      switch (token) {
        case "+":
          values.push(left + right);
          break;
        case "-":
          values.push(left - right);
          break;
        case "*":
          values.push(left * right);
          break;
        case "/":
          if (right === 0n) return { ok: false, error: "division by zero" };
          values.push(left / right);
          break;
      }
    } else {
      values.push(BigInt(token));
    }
  }

  return { ok: true, value: Number(values[0]) };
}

