export function lis_length(xs: number[]): [number, number] {
  const values = [...new Set(xs.filter((x) => !Number.isNaN(x)))];
  values.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

  const ranks = new Map<number, number>();
  for (let i = 0; i < values.length; i++) {
    ranks.set(values[i], i + 1);
  }

  const lengths = new Array<number>(values.length + 1).fill(0);
  const counts = new Array<number>(values.length + 1).fill(0);
  let bestLength = 0;
  let bestCount = 0;

  for (const x of xs) {
    const rank = ranks.get(x);
    let prefixLength = 0;
    let prefixCount = 0;

    if (rank !== undefined) {
      for (let i = rank - 1; i > 0; i -= (i & -i) >>> 0) {
        if (lengths[i] > prefixLength) {
          prefixLength = lengths[i];
          prefixCount = counts[i];
        } else if (lengths[i] === prefixLength) {
          prefixCount += counts[i];
        }
      }
    }

    const length = prefixLength + 1;
    const count = prefixLength === 0 ? 1 : prefixCount;

    if (rank !== undefined) {
      for (let i = rank; i <= values.length; i += (i & -i) >>> 0) {
        if (length > lengths[i]) {
          lengths[i] = length;
          counts[i] = count;
        } else if (length === lengths[i]) {
          counts[i] += count;
        }
      }
    }

    if (length > bestLength) {
      bestLength = length;
      bestCount = count;
    } else if (length === bestLength) {
      bestCount += count;
    }
  }

  return [bestLength, bestCount];
}

