type OrderEvent =
  | { kind: "Create"; id: string }
  | { kind: "Pay"; id: string }
  | { kind: "Ship"; id: string }
  | { kind: "Cancel"; id: string };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

type OrderState = "created" | "paid" | "shipped" | "cancelled";

export function order_states(events: OrderEvent[]): Result<([string, string])[]> {
  const orders = new Map<string, OrderState>();

  for (const { kind, id } of events) {
    const state = orders.get(id);

    if (kind === "Create") {
      if (state !== undefined) {
        return { ok: false, error: `duplicate order: ${id}` };
      }
      orders.set(id, "created");
      continue;
    }

    if (state === undefined) {
      return { ok: false, error: `unknown order: ${id}` };
    }

    if (kind === "Pay" && state === "created") {
      orders.set(id, "paid");
    } else if (kind === "Ship" && state === "paid") {
      orders.set(id, "shipped");
    } else if (kind === "Cancel" && (state === "created" || state === "paid")) {
      orders.set(id, "cancelled");
    } else {
      return { ok: false, error: `cannot ${kind.toLowerCase()} ${id} from ${state}` };
    }
  }

  const value = [...orders].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return { ok: true, value };
}

