type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_csv_line(s: string): Result<string[]> {
  const fields: string[] = [];
  let i = 0;

  while (true) {
    if (s[i] === '"') {
      i++;
      const parts: string[] = [];
      let start = i;

      while (true) {
        const quote = s.indexOf('"', i);
        if (quote === -1) {
          return { ok: false, error: "unterminated quote" };
        }

        parts.push(s.slice(start, quote));
        i = quote + 1;

        if (s[i] !== '"') {
          break;
        }

        parts.push('"');
        i++;
        start = i;
      }

      if (i < s.length && s[i] !== ",") {
        return { ok: false, error: `expected comma at ${i}` };
      }
      fields.push(parts.join(""));
    } else {
      const start = i;
      while (i < s.length && s[i] !== ",") {
        if (s[i] === '"') {
          return { ok: false, error: `unexpected quote at ${i}` };
        }
        i++;
      }
      fields.push(s.slice(start, i));
    }

    if (i === s.length) {
      return { ok: true, value: fields };
    }
    i++;
  }
}

