export function parse_money(s: string): Result<number> {
  const negative = s.startsWith("-");
  const dollarIndex = negative ? 1 : 0;
  if (s[dollarIndex] !== "$") {
    return { ok: false, error: "missing $" };
  }

  const dotIndex = s.indexOf(".");
  let cents = 0;
  if (dotIndex !== -1) {
    const centsText = s.slice(dotIndex + 1);
    if (!/^[0-9]{2}$/.test(centsText)) {
      return { ok: false, error: "bad cents" };
    }
    cents = Number(centsText);
  }

  const dollarsText = s.slice(dollarIndex + 1, dotIndex === -1 ? s.length : dotIndex);
  if (!/^(?:[0-9]+|[0-9]{1,3}(?:,[0-9]{3})+)$/.test(dollarsText)) {
    return { ok: false, error: "bad dollars" };
  }

  const digits = dollarsText.replace(/,/g, "");
  if (digits.length > 1 && digits.startsWith("0")) {
    return { ok: false, error: "bad dollars" };
  }

  const amount = Number(digits) * 100 + cents;
  return { ok: true, value: negative ? -amount : amount };
}

