type Employee = { name: string; dept: string; hours: number; rate_cents: number };

function compareCodePoints(a: string, b: string): number {
  const right = b[Symbol.iterator]();

  for (const char of a) {
    const next = right.next();
    if (next.done) return 1;

    const difference = (char.codePointAt(0) ?? 0) - (next.value.codePointAt(0) ?? 0);
    if (difference !== 0) return difference;
  }

  return right.next().done ? 0 : -1;
}

export function payroll_by_dept(emps: Employee[]): ([string, number])[] {
  const totals = new Map<string, number>();

  for (const { dept, hours, rate_cents } of emps) {
    const regularPay = Math.min(hours, 40) * rate_cents;
    const overtimePay =
      hours > 40 ? Math.floor(((hours - 40) * rate_cents * 3) / 2) : 0;
    totals.set(dept, (totals.get(dept) ?? 0) + regularPay + overtimePay);
  }

  return Array.from(totals).sort(
    ([deptA, totalA], [deptB, totalB]) =>
      totalB - totalA || compareCodePoints(deptA, deptB),
  );
}

