type Cmd = { kind: "Forward"; steps: number } | { kind: "TurnLeft" } | { kind: "TurnRight" };

export function robot_walk(cmds: Cmd[], obstacles: ([number, number])[]): [number, number, string] {
  const directions = [
    { dx: 0, dy: 1, name: "N" },
    { dx: 1, dy: 0, name: "E" },
    { dx: 0, dy: -1, name: "S" },
    { dx: -1, dy: 0, name: "W" },
  ];
  const blocked = new Set(obstacles.map(([x, y]) => `${x},${y}`));

  let x = 0;
  let y = 0;
  let heading = 0;

  for (const cmd of cmds) {
    switch (cmd.kind) {
      case "TurnLeft":
        heading = (heading + 3) % 4;
        break;
      case "TurnRight":
        heading = (heading + 1) % 4;
        break;
      case "Forward": {
        const { dx, dy } = directions[heading];
        for (let step = 1; step <= cmd.steps; step++) {
          const nextX = x + dx;
          const nextY = y + dy;
          if (blocked.has(`${nextX},${nextY}`)) {
            break;
          }
          x = nextX;
          y = nextY;
        }
        break;
      }
    }
  }

  return [x, y, directions[heading].name];
}

