type Expense = { payer: string; amount_cents: number };

export function settle_debts(
  expenses: Expense[],
  people: string[],
): ([string, string, number])[] {
  const paid = new Map<string, bigint>();
  let total = 0n;

  for (const { payer, amount_cents } of expenses) {
    const amount = BigInt(amount_cents);
    paid.set(payer, (paid.get(payer) ?? 0n) + amount);
    total += amount;
  }

  const count = BigInt(people.length);
  const remainder = ((total % count) + count) % count;
  const share = (total - remainder) / count;
  const balances = people.map(
    (person, i) =>
      (paid.get(person) ?? 0n) - share - (BigInt(i) < remainder ? 1n : 0n),
  );

  const payments: [string, string, number][] = [];
  while (true) {
    let debtor = -1;
    let creditor = -1;
    let lowest = 0n;
    let highest = 0n;

    for (let i = 0; i < balances.length; i++) {
      const balance = balances[i];
      if (balance < lowest) {
        lowest = balance;
        debtor = i;
      }
      if (balance > highest) {
        highest = balance;
        creditor = i;
      }
    }

    if (debtor === -1 || creditor === -1) {
      return payments;
    }

    const amount = -lowest < highest ? -lowest : highest;
    balances[debtor] += amount;
    balances[creditor] -= amount;
    payments.push([people[debtor], people[creditor], Number(amount)]);
  }
}

