type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function sliding_window_max(xs: number[], k: number): Result<number[]> {
  if (k < 1) {
    return { ok: false, error: "window must be positive" };
  }
  if (k > xs.length) {
    return { ok: false, error: "window larger than input" };
  }

  const maxima: number[] = [];
  const deque: number[] = [];
  let head = 0;
  let tail = 0;

  for (let i = 0; i < xs.length; i++) {
    while (head < tail && deque[head] <= i - k) {
      head++;
    }

    const value = xs[i];
    while (
      head < tail &&
      Object.is(Math.max(xs[deque[tail - 1]], value), value)
    ) {
      tail--;
    }
    deque[tail++] = i;

    if (i >= k - 1) {
      maxima.push(xs[deque[head]]);
    }
  }

  return { ok: true, value: maxima };
}

