function decimalParts(value: number): [bigint, number] {
  const [mantissa, exponent = "0"] = value.toString().split("e");
  const [whole, fraction = ""] = mantissa.split(".");
  return [BigInt(whole + fraction), Number(exponent) - fraction.length];
}

export function min_coins(
  coins: number[],
  amount: number,
): [number, number[]] | null {
  if (amount === 0) return [0, []];
  if (amount < 0 || !Number.isFinite(amount)) return null;

  const values = [...new Set(coins)]
    .filter((coin) => coin > 0 && coin <= amount)
    .sort((a, b) => b - a);
  if (values.length === 0) return null;

  const [targetDigits, targetPower] = decimalParts(amount);
  const parts = values.map(decimalParts);
  let commonPower = targetPower;
  for (const [, power] of parts) {
    commonPower = Math.min(commonPower, power);
  }

  const scale = (digits: bigint, power: number): bigint =>
    digits * 10n ** BigInt(power - commonPower);
  const target = scale(targetDigits, targetPower);
  const steps = parts.map(([digits, power]) => scale(digits, power));

  type State = {
    remaining: bigint;
    coin: number;
    previous: State | null;
