type Session = { user: string; kind: string; time: number };

function compareUsers(a: string, b: string): number {
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    const x = a.codePointAt(i)!;
    const y = b.codePointAt(j)!;
    if (x !== y) return x - y;
    i += x > 0xffff ? 2 : 1;
    j += y > 0xffff ? 2 : 1;
  }
  return (a.length - i) - (b.length - j);
}

export function session_totals(events: Session[]): ([string, number])[] {
  const users = new Map<string, { start: number | undefined; total: number }>();
  let lastTime = 0;

  for (const { user, kind, time } of events) {
    lastTime = time;
    let state = users.get(user);
    if (state === undefined) {
      state = { start: undefined, total: 0 };
      users.set(user, state);
    }

    if (kind === "login") {
      if (state.start === undefined) state.start = time;
    } else if (state.start !== undefined) {
      state.total += time - state.start;
      state.start = undefined;
    }
  }

  const result: [string, number][] = [];
  for (const [user, { start, total }] of users) {
    result.push([user, start === undefined ? total : total + (lastTime - start)]);
  }
  return result.sort(([a], [b]) => compareUsers(a, b));
}

