type Student = { name: string; scores: number[] };

function compareNames(a: string, b: string): number {
  const right = b[Symbol.iterator]();

  for (const leftChar of a) {
    const next = right.next();
    if (next.done) return 1;

    const difference = leftChar.codePointAt(0)! - next.value.codePointAt(0)!;
    if (difference !== 0) return difference;
  }

  return right.next().done ? 0 : -1;
}

export function student_medians(students: Student[]): ([string, number])[] {
  const result: [string, number][] = [];

  for (const { name, scores } of students) {
    if (scores.length === 0) continue;

    const sorted = [...scores].sort((a, b) => a - b);
    const middle = Math.floor(sorted.length / 2);
    let median = sorted[middle];

    if (sorted.length % 2 === 0) {
      const lower = sorted[middle - 1];
      const sum = lower + median;
      median = !Number.isFinite(sum) && Number.isFinite(lower) && Number.isFinite(median)
        ? lower / 2 + median / 2
        : sum / 2;
    }

    result.push([name, median]);
  }

  return result.sort(([nameA, medianA], [nameB, medianB]) =>
    medianB - medianA || compareNames(nameA, nameB)
  );
}

