      case "Swap": {
        const b = stack[stack.length - 1];
        const a = stack[stack.length - 2];
        stack.length -= 2;

        if (instr.kind === "Add") {
          stack.push(a + b);
        } else if (instr.kind === "Sub") {
          stack.push(a - b);
        } else if (instr.kind === "Mul") {
          stack.push(a * b);
        } else {
          stack.push(b, a);
        }
        break;
      }
      case "Dup":
        stack.push(stack[stack.length - 1]);
        break;
      case "Print":
        output.push(stack[stack.length - 1]);
        stack.pop();
        break;
      case "Jz": {
        const value = stack.pop();
        if (value === 0) {
          pc = instr.target;
          continue;
        }
        break;
      }
      case "Jmp":
        pc = instr.target;
        continue;
      case "Halt":
        return { ok: true, value: output };
    }

    pc += 1;
  }

  return { ok: true, value: output };
}

