type Event = { kind: "Coin"; cents: number } | { kind: "Select"; price: number } | { kind: "Refund" };

export function vending_machine(events: Event[]): string[] {
  let credit = 0;
  const messages: string[] = [];

  for (const event of events) {
    switch (event.kind) {
      case "Coin":
        if (event.cents === 5 || event.cents === 10 || event.cents === 25 || event.cents === 100) {
          credit += event.cents;
        } else {
          messages.push(`reject ${event.cents}`);
        }
        break;
      case "Select":
        if (credit >= event.price) {
          messages.push(`vend ${event.price} change ${credit - event.price}`);
          credit = 0;
        } else {
          messages.push(`insufficient ${credit}`);
        }
        break;
      case "Refund":
        if (credit > 0) {
          messages.push(`refund ${credit}`);
          credit = 0;
        }
        break;
    }
  }

  if (credit > 0) {
    messages.push(`refund ${credit}`);
  }

  return messages;
}

