type Person {
  name: String,
  age: Int,
}

fn decimal_sum(left: Int, right: Int) -> String {
  var a = left
  var b = right
  var carry = 0
  var text = ""
  while a > 0 || b > 0 || carry > 0 {
    let digit_sum = a % 10 + b % 10 + carry
    text = to_string(digit_sum % 10) + text
    carry = digit_sum / 10
    a = a / 10
    b = b / 10
  }
  if text == "" {
    return "0"
  }
  return text
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width")
  }
  for person in people {
    if person.age < 0 {
      return Err("negative age: " + person.name)
    }
  }

  var counts = map_from([(-1, 0)])
  var lowest = 0
  var highest = -1
  for person in people {
    let bucket = person.age / width
    if highest == -1 || bucket < lowest {
      lowest = bucket
    }
    highest = max(highest, bucket)
    let count = unwrap_or(map_get(counts, bucket), 0)
    counts = map_set(counts, bucket, count + 1)
  }

  var rows = []
  var bucket = lowest
  while bucket <= highest {
    let start = bucket * width
    let label = to_string(start) + "-" + decimal_sum(start, width - 1)
    let count = unwrap_or(map_get(counts, bucket), 0)
    rows = append(rows, (label, count))
    if bucket == highest {
      break
    }
    bucket = bucket + 1
  }
  return Ok(rows)
}

