  if len(usable) == 0 {
    return None
  }

  var best = map_from([(0, (0, 0))])
  var subtotal = 0
  while subtotal < amount {
    subtotal = subtotal + 1
    var best_count = 0
    var best_coin = 0
    for coin in usable {
