  return join(split(s, "+"), " ")
}

fn parse_query(s: String) -> Result[List[(String, String)], String] {
  var pairs = []
  for item in split(s, "&") {
    if item != "" {
      let parts = split(item, "=")
      let key = decode_plus(unwrap_or(first(parts), ""))
      if key == "" {
        return Err("empty key: " + item)
      }
      let value = decode_plus(join(drop(parts, 1), "="))
      pairs = append(pairs, (key, value))
    }
  }
  return Ok(pairs)
}

