# A root stores its component size as a negative number.
# Other entries store the index of their parent.
fn contact_root(forest: Map[Int, Int], index: Int) -> Int {
  var root = index
  var parent = unwrap_or(map_get(forest, root), -1)
  while parent >= 0 {
    root = parent
    parent = unwrap_or(map_get(forest, root), -1)
  }
  return root
}

fn link_contacts(forest: Map[Int, Int], left: Int, right: Int) -> Map[Int, Int] {
  let a = contact_root(forest, left)
  let b = contact_root(forest, right)
  if a == b {
    return forest
  }
  let size_a = unwrap_or(map_get(forest, a), -1)
  let size_b = unwrap_or(map_get(forest, b), -1)
  let combined = size_a + size_b
  if size_a <= size_b {
    return map_set(map_set(forest, a, combined), b, a)
  }
  return map_set(map_set(forest, b, combined), a, b)
}

fn fill_empty_fields(earlier: Contact, later: Contact) -> Contact {
  var merged = earlier
  if merged.name == "" {
    merged.name = later.name
  }
  if merged.email == "" {
    merged.email = later.email
  }
  if merged.phone == "" {
    merged.phone = later.phone
  }
  return merged
}

fn merge_contacts(contacts: List[Contact]) -> List[Contact] {
  let indexed = enumerate(contacts)
  let no_indices = range(0, 0)
  let no_keys = take([""], 0)
  var seen = map_from(zip(no_keys, no_indices))
  var forest = indexed
    |> map(|i, c| (i, -1))
    |> map_from()
  for (i, contact) in indexed {
    let email = trim(contact.email)
    let phone = phone_digits(contact.phone)
    for key in ["e:" + email, "p:" + phone] {
      if str_len(key) > 2 {
        let previous = unwrap_or(map_get(seen, key), -1)
        if previous < 0 {
          seen = map_set(seen, key, i)
        } else {
          forest = link_contacts(forest, i, previous)
        }
      }
    }
  }
  var merged = map_from(zip(no_indices, contacts))
  for (i, contact) in indexed {
    let root = contact_root(forest, i)
    let updated = match map_get(merged, root) {
      Some(earlier) => fill_empty_fields(earlier, contact),
