type Session {
  user: String,
  kind: String,
  time: Int,
}

fn user_total(events: List[Session], end_time: Int) -> Int {
  var logged_in = false
  var started_at = 0
  var total = 0
  for event in events {
    if event.kind == "login" {
      if !logged_in {
        started_at = event.time
        logged_in = true
      }
    } else if logged_in {
      total = total + (event.time - started_at)
      logged_in = false
    }
  }
  if logged_in {
    total = total + (end_time - started_at)
  }
  return total
}

fn session_totals(events: List[Session]) -> List[(String, Int)] {
  let end_time = match last(events) {
    Some(event) => event.time,
    None => 0,
  }
  return events
    |> group_by(|event| event.user)
    |> map(|user, sessions| (user, user_total(sessions, end_time)))
    |> sort_by(|entry| entry.0)
}

