fn median(scores: List[Int]) -> Float {
  let sorted = sort_by(scores, |score| score)
  let count = len(sorted)
  let middle = count / 2
  let upper = drop(sorted, middle)
    |> first()
    |> unwrap_or(0)
    |> to_float()
  if count % 2 != 0 {
    return upper
  }
  let lower = drop(sorted, middle - 1)
    |> first()
    |> unwrap_or(0)
    |> to_float()
  return (lower + upper) / 2.0
}

