        quantity = quantities[sku] + txn["delta"]
        if quantity < 0:
            return {"ok": False, "error": f"txn {position}: {sku} would go negative"}

        quantities[sku] = quantity

    final_stock: list[Stock] = [
        {"sku": sku, "qty": quantity}
        for sku, quantity in sorted(quantities.items())
        if quantity > 0
    ]
    return {"ok": True, "value": final_stock}

