export function compare_versions(a: string, b: string): Result<number> {
  const validVersion = /^[0-9]+(?:\.[0-9]+){0,3}(?![\s\S])/;

  if (!validVersion.test(a)) {
    return { ok: false, error: "bad version: " + a };
  }
  if (!validVersion.test(b)) {
    return { ok: false, error: "bad version: " + b };
  }

  const aParts = a.split(".");
  const bParts = b.split(".");

  for (let i = 0; i < Math.max(aParts.length, bParts.length); i++) {
    const left = (aParts[i] ?? "0").replace(/^0+/, "");
    const right = (bParts[i] ?? "0").replace(/^0+/, "");

    if (left.length !== right.length) {
      return { ok: true, value: left.length < right.length ? -1 : 1 };
    }
    if (left !== right) {
      return { ok: true, value: left < right ? -1 : 1 };
    }
  }

  return { ok: true, value: 0 };
}

