type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bowling_score(rolls: number[]): Result<number> {
  for (const pins of rolls) {
    if (pins < 0 || pins > 10) {
      return { ok: false, error: "invalid roll" };
    }
  }

  const incomplete: Result<number> = { ok: false, error: "incomplete game" };
  let next = 0;
  let score = 0;

  for (let frame = 1; frame <= 9; frame++) {
    const first = rolls[next++];
    if (first === undefined) return incomplete;

    // A missing lookahead roll will be caught when reading its frame.
    if (first === 10) {
      score += 10 + (rolls[next] ?? 0) + (rolls[next + 1] ?? 0);
      continue;
    }

    const second = rolls[next++];
    if (second === undefined) return incomplete;

    const total = first + second;
    if (total > 10) {
      return { ok: false, error: `too many pins in frame ${frame}` };
    }
    score += total + (total === 10 ? (rolls[next] ?? 0) : 0);
  }

  const first = rolls[next++];
  const second = rolls[next++];
  if (first === undefined || second === undefined) return incomplete;

  const total = first + second;
  if (first !== 10 && total > 10) {
    return { ok: false, error: "too many pins in frame 10" };
  }
  score += total;

  if (first === 10 || total === 10) {
    const third = rolls[next++];
    if (third === undefined) return incomplete;
    if (first === 10 && second !== 10 && second + third > 10) {
      return { ok: false, error: "too many pins in frame 10" };
    }
    score += third;
  }

  if (next < rolls.length) return { ok: false, error: "too many rolls" };
  return { ok: true, value: score };
}

