export function count_islands(grid: string[]): [number, number] {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  if (width === 0) return [0, 0];

  const visited = grid.map(() => new Uint8Array(width));
  const stack: [number, number][] = [];
  let islands = 0;
  let largest = 0;

  function enqueue(row: number, col: number): void {
    if (
      row < 0 || row >= height || col < 0 || col >= width ||
      grid[row][col] !== "#" || visited[row][col] !== 0
    ) {
      return;
    }
    visited[row][col] = 1;
    stack.push([row, col]);
  }

  for (let row = 0; row < height; row++) {
    for (let col = 0; col < width; col++) {
      enqueue(row, col);
      if (stack.length === 0) continue;

      islands++;
      let size = 0;
      let cell = stack.pop();
      while (cell !== undefined) {
        const [r, c] = cell;
        size++;
        enqueue(r - 1, c);
        enqueue(r + 1, c);
        enqueue(r, c - 1);
        enqueue(r, c + 1);
        cell = stack.pop();
      }
      largest = Math.max(largest, size);
    }
  }

  return [islands, largest];
}

