export function elevator_scan(
  start: number,
  requests: number[],
  direction: string,
): number[] {
  const distinct = new Set(requests);
  const above: number[] = [];
  const below: number[] = [];

  for (const floor of distinct) {
    if (floor > start) {
      above.push(floor);
    } else if (floor < start) {
      below.push(floor);
    }
  }

  above.sort((a, b) => a - b);
  below.sort((a, b) => b - a);

  const first = distinct.has(start) ? [start] : [];
  return direction === "down"
    ? first.concat(below, above)
    : first.concat(above, below);
}

