export function edit_script_distance(a: string, b: string): number {
  const source = Array.from(a);
  const target = Array.from(b);
  const width = target.length + 1;

  let twoBack = new Array<number>(width).fill(0);
  let previous = Array.from({ length: width }, (_, j) => j);
  let current = new Array<number>(width).fill(0);

  for (let i = 1; i <= source.length; i++) {
    current[0] = i;

    for (let j = 1; j < width; j++) {
      const replacementCost = source[i - 1] === target[j - 1] ? 0 : 1;
      let cost = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + replacementCost,
      );

      if (
        i >= 2 &&
        j >= 2 &&
        source[i - 1] === target[j - 2] &&
        source[i - 2] === target[j - 1]
      ) {
        cost = Math.min(cost, twoBack[j - 2] + 1);
      }

      current[j] = cost;
    }

    const spare = twoBack;
    twoBack = previous;
    previous = current;
    current = spare;
  }

  return previous[target.length];
}

