export function heading_numbers(lines: string[]): string[] {
  const counters = [0, 0, 0];
  const output: string[] = [];

  for (const line of lines) {
    const heading = /^(#{1,3}) /.exec(line);
    if (heading === null || heading[0].length === line.length) {
      continue;
    }

    const level = heading[1].length;
    counters[level - 1] += 1;
    counters.fill(0, level);

    const title = line.slice(heading[0].length);
    output.push(`${counters.slice(0, level).join(".")} ${title}`);
  }

  return output;
}

