export function glob_match(pattern: string, s: string): boolean {
  const tokens = Array.from(pattern);
  const chars = Array.from(s);
  const reachable = new Uint8Array(chars.length + 1);
  reachable[0] = 1;

  for (let i = 0; i < tokens.length; i++) {
    let token = tokens[i];

    if (token === "*") {
      for (let j = 1; j <= chars.length; j++) {
        if (reachable[j - 1] === 1) {
          reachable[j] = 1;
        }
      }
      continue;
    }

    const wildcard = token === "?";
    if (token === "\\" && i + 1 < tokens.length) {
      token = tokens[++i];
    }

    for (let j = chars.length; j > 0; j--) {
      reachable[j] = wildcard || token === chars[j - 1] ? reachable[j - 1] : 0;
    }
    reachable[0] = 0;
  }

  return reachable[chars.length] === 1;
}

