type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function flatten_nested(s: string): Result<[number[], number]> {
  const text = s.replace(/ /g, "");
  const values: number[] = [];

  let i = 0;
  const invalid = (): Result<[number[], number]> => ({
    ok: false,
    error: `invalid at ${i}`,
  });

  const isDigit = (index: number): boolean => {
    const code = text.charCodeAt(index);
    return code >= 48 && code <= 57;
  };

  if (text[i] !== "[") return invalid();
  i++;

  let depth = 1;
  let maxDepth = 1;
  let state: "first" | "element" | "separator" = "first";

  while (i < text.length) {
    const ch = text[i];

    if (ch === "]" && state !== "element") {
      i++;
      depth--;
      if (depth === 0) {
        if (i !== text.length) return invalid();
        return { ok: true, value: [values, maxDepth] };
      }
      state = "separator";
    } else if (state === "separator") {
      if (ch !== ",") return invalid();
      i++;
      state = "element";
    } else if (ch === "[") {
      i++;
      depth++;
      maxDepth = Math.max(maxDepth, depth);
      state = "first";
