type Match = { home: string; away: string; home_goals: number; away_goals: number };

type Row = [string, number, number, number];

function compareNames(a: string, b: string): number {
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    const left = a.codePointAt(i)!;
    const right = b.codePointAt(j)!;
    if (left !== right) return left - right;
    i += left > 0xffff ? 2 : 1;
    j += right > 0xffff ? 2 : 1;
  }
  return (a.length - i) - (b.length - j);
}

export function league_table(matches: Match[]): ([string, number, number, number])[] {
  const teams = new Map<string, Row>();

  function record(team: string, scored: number, conceded: number): void {
    let row = teams.get(team);
    if (row === undefined) {
      row = [team, 0, 0, 0];
      teams.set(team, row);
    }
    row[1] += scored > conceded ? 3 : scored === conceded ? 1 : 0;
    row[2] += scored - conceded;
    row[3] += scored;
  }

  for (const { home, away, home_goals, away_goals } of matches) {
    record(home, home_goals, away_goals);
    record(away, away_goals, home_goals);
  }

  return Array.from(teams.values()).sort(
    (a, b) => b[1] - a[1] || b[2] - a[2] || b[3] - a[3] || compareNames(a[0], b[0]),
  );
}

