export function life_step(grid: string[], steps: number): string[] {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  let current = grid.slice();

  if (width === 0) {
    return current;
  }

  for (let generation = 0; generation < steps; generation++) {
    const next: string[] = [];

    for (let row = 0; row < height; row++) {
      const cells: string[] = [];

      for (let col = 0; col < width; col++) {
        let neighbors = 0;

        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) {
              continue;
            }
            if (current[row + dr]?.[col + dc] === "#") {
              neighbors++;
            }
          }
        }

        const alive = current[row][col] === "#";
        cells.push(neighbors === 3 || (alive && neighbors === 2) ? "#" : ".");
      }

      next.push(cells.join(""));
    }

    current = next;
  }

  return current;
}

