type Result<T> = { ok: true; value: T } | { ok: false; error: string };

type Operator = "+" | "-" | "*" | "/";
type Token = Operator | { digits: string };

function precedence(op: Operator): number {
  return op === "*" || op === "/" ? 2 : 1;
}

function isDigit(ch: string | undefined): boolean {
  return ch !== undefined && ch >= "0" && ch <= "9";
}

export function eval_expr(s: string): Result<number> {
  const input = s.replace(/ /g, "");
  const postfix: Token[] = [];
  const operators: (Operator | "(")[] = [];
  let i = 0;
  let depth = 0;
  let needFactor = true;

  function unexpected(): Result<number> {
    const point = input.codePointAt(i);
    return {
      ok: false,
      error: point === undefined
        ? "unexpected end"
        : "unexpected character: " + String.fromCodePoint(point),
    };
  }

  while (i < input.length) {
    const ch = input[i];
    if (needFactor) {
      if (isDigit(ch)) {
        const start = i++;
        while (isDigit(input[i])) i++;
        postfix.push({ digits: input.slice(start, i) });
        needFactor = false;
      } else if (ch === "(") {
        operators.push(ch);
        depth++;
        i++;
      } else {
        return unexpected();
      }
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/") {
      while (operators.length > 0) {
        const top = operators[operators.length - 1];
        if (top === "(" || precedence(top) < precedence(ch)) break;
        postfix.push(top);
        operators.pop();
      }
      operators.push(ch);
      needFactor = true;
      i++;
    } else if (ch === ")" && depth > 0) {
      for (let top = operators.pop(); top !== undefined && top !== "("; top = operators.pop()) {
        postfix.push(top);
      }
      depth--;
      i++;
    } else {
      return unexpected();
    }
  }

  if (needFactor || depth !== 0) return unexpected();

  for (let op = operators.pop(); op !== undefined; op = operators.pop()) {
    if (op !== "(") postfix.push(op);
  }

  const values: bigint[] = [];
  for (const token of postfix) {
    if (typeof token === "object") {
      values.push(BigInt(token.digits));
    } else {
      const right = values[values.length - 1];
      const left = values[values.length - 2];
      values.length -= 2;

      switch (token) {
        case "+":
          values.push(left + right);
          break;
        case "-":
          values.push(left - right);
          break;
        case "*":
          values.push(left * right);
          break;
        case "/":
          if (right === 0n) return { ok: false, error: "division by zero" };
          values.push(left / right);
          break;
      }
    }
  }

  return { ok: true, value: Number(values[0]) };
}

