export function parse_config(lines: string[]): Result<Setting[]> {
  const settings: Setting[] = [];
  const sections = new Map<string, Map<string, Setting>>();
  let section = "";

  for (const [index, rawLine] of lines.entries()) {
    const line = rawLine.trim();
    if (line === "" || line.startsWith("#")) {
      continue;
    }

    if (line.startsWith("[")) {
      const name = line.slice(1, -1).trim();
      if (!line.endsWith("]") || name === "") {
        return { ok: false, error: `line ${index + 1}: bad header` };
      }
      section = name;
      continue;
    }

    const separator = line.indexOf("=");
    if (separator === -1) {
      return { ok: false, error: `line ${index + 1}: missing =` };
    }

    const key = line.slice(0, separator).trim();
    if (key === "") {
      return { ok: false, error: `line ${index + 1}: empty key` };
    }
    const value = line.slice(separator + 1).trim();

    let entries = sections.get(section);
    if (entries === undefined) {
      entries = new Map<string, Setting>();
      sections.set(section, entries);
    }

    const existing = entries.get(key);
    if (existing === undefined) {
      const setting: Setting = { section, key, value };
      entries.set(key, setting);
      settings.push(setting);
    } else {
      existing.value = value;
    }
  }

  return { ok: true, value: settings };
}

