type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_duration(s: string): Result<number> {
  if (s.length === 0) {
    return { ok: false, error: "empty" };
  }

  let total = 0;
  let numberStart = 0;
  let lastUnit = -1;
  let index = 0;

  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      index += 1;
      continue;
    }

    let unit: number;
    let multiplier: number;
    switch (ch) {
      case "h":
        unit = 0;
        multiplier = 3600;
        break;
      case "m":
        unit = 1;
        multiplier = 60;
        break;
      case "s":
        unit = 2;
        multiplier = 1;
        break;
      default:
        return { ok: false, error: `unknown unit: ${ch}` };
    }

    if (numberStart === index) {
      return { ok: false, error: `missing number before ${ch}` };
    }
    if (unit <= lastUnit) {
      return { ok: false, error: `unit out of order: ${ch}` };
    }

    total += Number(s.slice(numberStart, index)) * multiplier;
    lastUnit = unit;
    index += 1;
    numberStart = index;
  }

  if (numberStart !== s.length) {
    return { ok: false, error: "missing unit" };
  }
  return { ok: true, value: total };
}

