export function rle_compress(s: string): string {
  const runs: string[] = [];
  let previous = "";
  let count = 0;

  for (const character of s) {
    if (character === previous) {
      count++;
    } else {
      if (count > 0) {
        runs.push(count === 1 ? previous : previous + count);
      }
      previous = character;
      count = 1;
    }
  }

  if (count > 0) {
    runs.push(count === 1 ? previous : previous + count);
  }

  const encoded = runs.join("");
  return encoded.length < s.length ? encoded : s;
}

