export function lis_length(xs: number[]): [number, number] {
  const values = [...new Set(xs.filter((x) => !Number.isNaN(x)))];
  values.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));

  const ranks = new Map<number, number>();
  for (let i = 0; i < values.length; i++) {
    ranks.set(values[i], i);
  }

  const tree = new Array<[number, bigint] | undefined>(values.length);
  let bestLength = 0;
  let bestCount = 0n;

  for (const x of xs) {
    const rank = ranks.get(x);
    let length = 1;
    let count = 1n;

    if (rank !== undefined) {
      let prefixLength = 0;
      let prefixCount = 0n;

      // Query only ranks strictly below the current rank.
      for (let i = rank; i > 0; i = (i & (i - 1)) >>> 0) {
        const entry = tree[i - 1];
        if (entry === undefined) continue;

        if (entry[0] > prefixLength) {
          [prefixLength, prefixCount] = entry;
        } else if (entry[0] === prefixLength) {
          prefixCount += entry[1];
        }
      }

      if (prefixLength > 0) {
        length = prefixLength + 1;
        count = prefixCount;
      }

      for (let i = rank; i < tree.length; i = (i | (i + 1)) >>> 0) {
        const entry = tree[i];
        if (entry === undefined || length > entry[0]) {
          tree[i] = [length, count];
        } else if (length === entry[0]) {
          entry[1] += count;
        }
      }
    }

    if (length > bestLength) {
      bestLength = length;
      bestCount = count;
    } else if (length === bestLength) {
      bestCount += count;
    }
  }

  return [bestLength, Number(bestCount)];
}

