          prefixCount += entry[1];
        }
      }

      if (prefixLength > 0) {
        length = prefixLength + 1;
        count = prefixCount;
      }

      for (let i = rank; i < tree.length; i = (i | (i + 1)) >>> 0) {
        const entry = tree[i];
        if (entry === undefined || length > entry[0]) {
          tree[i] = [length, count];
        } else if (length === entry[0]) {
          entry[1] += count;
        }
      }
    }

    if (length > bestLength) {
      bestLength = length;
      bestCount = count;
    } else if (length === bestLength) {
      bestCount += count;
    }
  }

  return [bestLength, Number(bestCount)];
}

