export function poker_hand(cards: string[]): string {
  if (cards.length !== 5) return "invalid";

  const ranks = "23456789TJQKA";
  const seen = new Set<string>();
  const rankCounts = new Map<number, number>();
  const suits = new Set<string>();

  for (const card of cards) {
    if (typeof card !== "string" || card.length !== 2 || seen.has(card)) {
      return "invalid";
    }

    const rank = ranks.indexOf(card.charAt(0));
    const suit = card.charAt(1);
    if (rank === -1 || !"CDHS".includes(suit)) return "invalid";

    seen.add(card);
    suits.add(suit);
    rankCounts.set(rank, (rankCounts.get(rank) ?? 0) + 1);
  }

  const distinctRanks = [...rankCounts.keys()].sort((a, b) => a - b);
  const straight =
    distinctRanks.length === 5 &&
    (distinctRanks[4] - distinctRanks[0] === 4 ||
      distinctRanks.join(",") === "0,1,2,3,12");
  const flush = suits.size === 1;
  const counts = [...rankCounts.values()].sort((a, b) => b - a);

  if (straight && flush) return "straight flush";
  if (counts[0] === 4) return "four of a kind";
  if (counts[0] === 3 && counts[1] === 2) return "full house";
  if (flush) return "flush";
  if (straight) return "straight";
  if (counts[0] === 3) return "three of a kind";
  if (counts[0] === 2 && counts[1] === 2) return "two pair";
  if (counts[0] === 2) return "one pair";
  return "high card";
}

