type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function rle_decode(s: string): Result<string> {
  if (/^[0-9]/.test(s)) {
    return { ok: false, error: "missing character before count" };
  }

  const groups: [string, string][] = [];
  for (const [, character, count] of s.matchAll(/([^0-9])([0-9]*)/gu)) {
    if (count.startsWith("0")) {
      return { ok: false, error: `bad count for ${character}` };
    }
    groups.push([character, count]);
  }

  const value = groups
    .map(([character, count]) => character.repeat(count === "" ? 1 : Number(count)))
    .join("");
  return { ok: true, value };
}

