export function robot_walk(cmds: Cmd[], obstacles: ([number, number])[]): [number, number, string] {
    const blocked = new Set(obstacles.map(([x, y]) => `${x},${y}`));
    const directions = ["N", "E", "S", "W"];
    const dx = [0, 1, 0, -1];
    const dy = [1, 0, -1, 0];

    let x = 0;
    let y = 0;
    let heading = 0;

    for (const cmd of cmds) {
        switch (cmd.kind) {
            case "TurnLeft":
                heading = (heading + 3) % 4;
                break;
            case "TurnRight":
                heading = (heading + 1) % 4;
                break;
            case "Forward":
                for (let step = 0; step < cmd.steps; step++) {
                    const nextX = x + dx[heading];
                    const nextY = y + dy[heading];
                    if (blocked.has(`${nextX},${nextY}`)) {
                        break;
                    }
                    x = nextX;
                    y = nextY;
                }
                break;
        }
    }

    return [x, y, directions[heading]];
}

