type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function sliding_window_max(xs: number[], k: number): Result<number[]> {
  if (k < 1) return { ok: false, error: "window must be positive" };
  if (k > xs.length) return { ok: false, error: "window larger than input" };

  const maxima: number[] = [];
  const deque: number[] = [];
  let head = 0;

  for (let i = 0; i < xs.length; i++) {
    const start = i - k + 1;
    while (head < deque.length && deque[head] < start) {
      head++;
    }

    const current = xs[i];
    while (head < deque.length) {
      const last = xs[deque[deque.length - 1]];
      if (!Object.is(Math.max(last, current), current)) break;
      deque.pop();
    }
    deque.push(i);

    if (start >= 0) maxima.push(xs[deque[head]]);
  }

  return { ok: true, value: maxima };
}

