export function tennis_score(points: string): string {
  let a = 0;
  let b = 0;
  let winner: "A" | "B" | undefined;

  for (const point of points) {
    if (winner !== undefined) {
      return "error: point after game";
    }

    if (point === "A") {
      a++;
    } else if (point === "B") {
      b++;
    } else {
      return "error: bad point";
    }

    if (a >= 4 && a - b >= 2) {
      winner = "A";
    } else if (b >= 4 && b - a >= 2) {
      winner = "B";
    }
  }

  if (winner !== undefined) {
    return `game ${winner}`;
  }

  if (a >= 3 && b >= 3) {
    return a === b ? "deuce" : a > b ? "advantage A" : "advantage B";
  }

  const names = ["love", "15", "30", "40"];
  return a === b ? `${names[a]}-all` : `${names[a]}-${names[b]}`;
}

