type Instr =
  | { kind: "Push"; n: number }
  | { kind: "Pop" }
  | { kind: "Add" }
  | { kind: "Sub" }
  | { kind: "Mul" }
  | { kind: "Dup" }
  | { kind: "Swap" }
  | { kind: "Jz"; target: number }
  | { kind: "Jmp"; target: number }
  | { kind: "Print" }
  | { kind: "Halt" };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function stack_vm(prog: Instr[]): Result<number[]> {
  const stack: number[] = [];
  const output: number[] = [];
  let pc = 0;
  let steps = 0;

  function pop(): number {
    return stack.pop()!;
  }

  while (pc < prog.length) {
    if (steps === 1000) {
      return { ok: false, error: "step limit exceeded" };
    }
    steps += 1;

    const instr = prog[pc];
    let needed = 0;
    switch (instr.kind) {
      case "Pop":
      case "Dup":
      case "Print":
      case "Jz":
        needed = 1;
        break;
      case "Add":
      case "Sub":
      case "Mul":
      case "Swap":
        needed = 2;
        break;
    }

    if (stack.length < needed) {
      return { ok: false, error: `stack underflow at ${pc}` };
    }

    if (
      (instr.kind === "Jz" || instr.kind === "Jmp") &&
      (!Number.isInteger(instr.target) ||
        instr.target < 0 ||
        instr.target >= prog.length)
    ) {
      return { ok: false, error: `bad jump at ${pc}` };
    }

    switch (instr.kind) {
      case "Push":
        stack.push(instr.n);
        break;
      case "Pop":
        pop();
        break;
      case "Add":
      case "Sub":
      case "Mul": {
        const b = pop();
        const a = pop();
        stack.push(instr.kind === "Add" ? a + b : instr.kind === "Sub" ? a - b : a * b);
        break;
      }
      case "Dup":
        stack.push(stack[stack.length - 1]);
        break;
      case "Swap": {
        const b = pop();
        const a = pop();
        stack.push(b, a);
        break;
      }
      case "Jz":
        if (pop() === 0) {
          pc = instr.target;
          continue;
        }
        break;
      case "Jmp":
        pc = instr.target;
        continue;
      case "Print":
        output.push(pop());
        break;
      case "Halt":
        return { ok: true, value: output };
    }

    pc += 1;
  }

  return { ok: true, value: output };
}

