export function min_coins(coins: number[], amount: number): [number, number[]] | null {
  if (!Number.isFinite(amount) || amount < 0) return null;
  if (amount === 0) return [0, []];

  const values = [...new Set(coins)]
    .filter((value) => Number.isFinite(value) && value > 0 && value <= amount)
    .sort((a, b) => b - a);
  if (values.length === 0) return null;

  // Use exact integer weights, even for fractional number inputs.
  const integral = Number.isSafeInteger(amount) && values.every(Number.isSafeInteger);
  const bits = new DataView(new ArrayBuffer(8));

  function weight(value: number): bigint {
    if (integral) return BigInt(value);
    bits.setFloat64(0, value);
    const raw = bits.getBigUint64(0);
    const exponent = (raw >> 52n) & 0x7ffn;
    const fraction = raw & ((1n << 52n) - 1n);
    return exponent === 0n
      ? fraction
      : ((1n << 52n) | fraction) << (exponent - 1n);
  }

  function gcd(a: bigint, b: bigint): bigint {
    while (b !== 0n) {
      const remainder = a % b;
      a = b;
      b = remainder;
    }
    return a;
  }

  const target = weight(amount);
  const denominations = values.map((value) => ({ value, weight: weight(value) }));
  const divisor = denominations.reduce((d, coin) => gcd(d, coin.weight), 0n);
  if (target % divisor !== 0n) return null;

  const queue: bigint[] = [target];
  const chosen = new Map<bigint, { value: number; weight: bigint }>();

  for (const remaining of queue) {
    for (const coin of denominations) {
      if (coin.weight > remaining) continue;
      const next = remaining - coin.weight;
      if (chosen.has(next)) continue;
      chosen.set(next, coin);

      if (next === 0n) {
        const used: number[] = [];
        let current = 0n;
        for (;;) {
          const step = chosen.get(current);
          if (step === undefined) break;
          used.push(step.value);
          current += step.weight;
        }
        used.reverse();
        return [used.length, used];
      }

      queue.push(next);
    }
  }

  return null;
}

