type Event = { kind: "Coin"; cents: number } | { kind: "Select"; price: number } | { kind: "Refund" };

export function vending_machine(events: Event[]): string[] {
  const messages: string[] = [];
  let credit = 0;

  for (const event of events) {
    switch (event.kind) {
      case "Coin": {
        const { cents } = event;
        if (cents === 5 || cents === 10 || cents === 25 || cents === 100) {
          credit += cents;
        } else {
          messages.push(`reject ${cents}`);
        }
        break;
      }
      case "Select": {
        const { price } = event;
        if (credit >= price) {
          messages.push(`vend ${price} change ${credit - price}`);
          credit = 0;
        } else {
          messages.push(`insufficient ${credit}`);
        }
        break;
      }
      case "Refund":
        if (credit > 0) {
          messages.push(`refund ${credit}`);
          credit = 0;
        }
        break;
    }
  }

  if (credit > 0) {
    messages.push(`refund ${credit}`);
  }

  return messages;
}

