type Token =
  | { kind: "Num"; value: number }
  | { kind: "Ident"; name: string }
  | { kind: "Sym"; text: string };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function isDigit(code: number): boolean {
  return code >= 48 && code <= 57;
}

function isIdentStart(code: number): boolean {
  return code === 95 || (code >= 97 && code <= 122);
}

export function tokenize(s: string): Result<Token[]> {
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    const ch = s.charAt(i);
    const code = s.charCodeAt(i);

    if (ch === " ") {
      i++;
      continue;
    }

    if (isDigit(code)) {
      const start = i++;
      while (isDigit(s.charCodeAt(i))) {
        i++;
      }
      tokens.push({ kind: "Num", value: Number(s.slice(start, i)) });
      continue;
    }

    if (isIdentStart(code)) {
      const start = i++;
      while (i < s.length) {
        const next = s.charCodeAt(i);
        if (!isIdentStart(next) && !isDigit(next)) {
          break;
        }
        i++;
      }
      tokens.push({ kind: "Ident", name: s.slice(start, i) });
      continue;
    }

    const pair = s.slice(i, i + 2);
    if (pair === "==" || pair === "<=" || pair === ">=" || pair === "!=") {
      tokens.push({ kind: "Sym", text: pair });
      i += 2;
      continue;
    }

    if ("+-*/=<>() ,".replace(" ", "").includes(ch)) {
      tokens.push({ kind: "Sym", text: ch });
      i++;
      continue;
    }

    return { ok: false, error: `unexpected character: ${ch} at ${i}` };
  }

  return { ok: true, value: tokens };
}

