  | Transfer(src: String, dst: String, amount: Int)

fn empty_balances() -> Map[String, Int] {
  return map_from([])
}

fn account_balance(balances: Map[String, Int], name: String) -> Result[Int, String] {
  return match map_get(balances, name) {
    Some(balance) => Ok(balance),
    None => Err("unknown account " + name),
  }
}

fn open_account(balances: Map[String, Int], name: String) -> Result[Map[String, Int], String] {
  return match map_get(balances, name) {
    Some(_) => Err("duplicate account " + name),
    None => Ok(map_set(balances, name, 0)),
  }
}

fn change_balance(
  balances: Map[String, Int],
  name: String,
  amount: Int,
  withdraw: Bool,
) -> Result[Map[String, Int], String] {
  let balance = try account_balance(balances, name)
  if amount <= 0 {
    return Err("invalid amount")
  }
  if withdraw {
    if amount > balance {
      return Err("insufficient funds")
    }
    return Ok(map_set(balances, name, balance - amount))
  }
  return Ok(map_set(balances, name, balance + amount))
}

fn transfer_balance(
  balances: Map[String, Int],
  src: String,
  dst: String,
  amount: Int,
) -> Result[Map[String, Int], String] {
  let src_balance = try account_balance(balances, src)
  let dst_balance = try account_balance(balances, dst)
  if src == dst {
    return Err("same account")
  }
  if amount <= 0 {
    return Err("invalid amount")
  }
  if amount > src_balance {
    return Err("insufficient funds")
  }
  let debited = map_set(balances, src, src_balance - amount)
  return Ok(map_set(debited, dst, dst_balance + amount))
}

fn apply_op(balances: Map[String, Int], op: BankOp) -> Result[Map[String, Int], String] {
  return match op {
    Open(name) => open_account(balances, name),
    Deposit(name, amount) => change_balance(balances, name, amount, false),
    Withdraw(name, amount) => change_balance(balances, name, amount, true),
    Transfer(src, dst, amount) => transfer_balance(balances, src, dst, amount),
  }
}

