fn parse_duration(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let limit = 9007199254740991
  var total = 0
  var number = 0
  var has_digits = false
  var last_rank = 0
  var overflow = false
  for ch in split(s, "") {
    let digit = digit_value(ch)
    if digit >= 0 {
      has_digits = true
      if !overflow && number <= (limit - digit) / 10 {
        number = number * 10 + digit
      } else {
        overflow = true
      }
    } else {
      let unit = match ch {
        "h" => (1, 3600),
        "m" => (2, 60),
        "s" => (3, 1),
        _ => (0, 1),
      }
      if unit.0 == 0 {
        return Err("unknown unit: " + ch)
      }
      if !has_digits {
        return Err("missing number before " + ch)
      }
      if unit.0 <= last_rank {
        return Err("unit out of order: " + ch)
      }
      if !overflow && number <= (limit - total) / unit.1 {
        total = total + number * unit.1
      } else {
        overflow = true
      }
      last_rank = unit.0
      number = 0
      has_digits = false
    }
  }
  if has_digits {
    return Err("missing unit")
  }
  if overflow {
    return Err("overflow")
  }
  return Ok(total)
}

