  while true {
    var debtor = ""
    var creditor = ""
    var debt = 0
    var credit = 0
    for person in people {
      let balance = unwrap_or(map_get(balances, person), 0)
      if balance < debt {
        debtor = person
        debt = balance
      } else if balance > credit {
        creditor = person
        credit = balance
      }
    }

    if debt == 0 {
      break
    }

    var amount = credit
    if debt > -credit {
      amount = -debt
    }
    balances = map_set(balances, debtor, debt + amount)
    balances = map_set(balances, creditor, credit - amount)
    payments = append(payments, (debtor, creditor, amount))
  }
  return payments
}

