fn row_cells(row: String) -> List[String] {
  let marks = ["X", "O", "."]
  for a in marks {
    for b in marks {
      for c in marks {
        if row == a + b + c {
          return [a, b, c]
        }
      }
    }
  }
  return []
}

fn cell_at(cells: List[String], index: Int) -> String {
  let suffix = drop(cells, index)
  return unwrap_or(first(suffix), ".")
}

fn has_line(cells: List[String], mark: String) -> Bool {
  let lines = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]
  for (a, b, c) in lines {
    let start = cell_at(cells, a)
    let middle = cell_at(cells, b)
    let end = cell_at(cells, c)
    if start == mark && middle == mark && end == mark {
      return true
    }
  }
  return false
}

fn tic_tac_toe(board: List[String]) -> String {
  if len(board) != 3 {
    return "invalid"
  }
  var cells = row_cells("")
  for row in board {
    let marks = row_cells(row)
    if len(marks) != 3 {
      return "invalid"
    }
    for mark in marks {
      cells = append(cells, mark)
    }
  }
  let x_count = len(filter(cells, |mark| mark == "X"))
  let o_count = len(filter(cells, |mark| mark == "O"))
  let lead = x_count - o_count
  if lead != 0 && lead != 1 {
    return "invalid"
  }
  let x_wins = has_line(cells, "X")
  let o_wins = has_line(cells, "O")
  if (x_wins && o_wins) || (x_wins && lead != 1) || (o_wins && lead != 0) {
    return "invalid"
  }
  if x_wins {
    return "X wins"
  }
  if o_wins {
    return "O wins"
  }
  if x_count + o_count == 9 {
    return "draw"
  }
  return "in progress"
}

