type Token =
  | Num(value: Int)
  | Ident(name: String)
  | Sym(text: String)

fn is_digit(c: String) -> Bool {
  return c >= "0" && c <= "9"
}

fn is_ident_start(c: String) -> Bool {
  return c == "_" || (c >= "a" && c <= "z")
}

fn is_ident_part(c: String) -> Bool {
  return is_ident_start(c) || is_digit(c)
}

fn char_at(chars: Map[Int, String], i: Int) -> String {
  return unwrap_or(map_get(chars, i), "")
}

fn read_run(chars: Map[Int, String], start: Int, accepts: fn(String) -> Bool) -> (String, Int) {
  var i = start
  var text = ""
  while true {
    let c = char_at(chars, i)
    if !accepts(c) {
      break
    }
    text = text + c
    i = i + 1
  }
  return (text, i)
}

fn empty_tokens() -> List[Token] {
  return []
}

fn tokenize(s: String) -> Result[List[Token], String] {
  let chars = split(s, "")
  let indexed = map_from(enumerate(chars))
  var tokens = empty_tokens()
  var i = 0
  while i < len(chars) {
    let c = char_at(indexed, i)
    if c == " " {
      i = i + 1
    } else if is_digit(c) {
      var start = i
      while char_at(indexed, start) == "0" {
        start = start + 1
      }
      let run = read_run(indexed, start, is_digit)
      let parsed = match run.0 {
        "" => Some(0),
        text => parse_int(text),
      }
      let number = match parsed {
        Some(value) => Ok(value),
        None => Err("integer out of range at " + to_string(i)),
      }
      let value = try number
      tokens = append(tokens, Num(value))
      i = run.1
    } else if is_ident_start(c) {
      let run = read_run(indexed, i, is_ident_part)
      tokens = append(tokens, Ident(run.0))
      i = run.1
    } else {
      let pair = c + char_at(indexed, i + 1)
      if contains(["==", "<=", ">=", "!="], pair) {
        tokens = append(tokens, Sym(pair))
        i = i + 2
      } else if contains(["+", "-", "*", "/", "=", "<", ">", "(", ")", ","], c) {
        tokens = append(tokens, Sym(c))
        i = i + 1
      } else {
        return Err("unexpected character: " + c + " at " + to_string(i))
      }
    }
  }
  return Ok(tokens)
}

