from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str


def _invalid(position: int) -> Err:
    return {"ok": False, "error": f"invalid at {position}"}


def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    text = s.replace(" ", "")
    if not text.startswith("["):
        return _invalid(0)

    values: list[int] = []
    length = len(text)
    position = 1
    depth = 1
    max_depth = 1
    state: Literal["first", "element", "separator"] = "first"

    while position < length:
        char = text[position]

        if char == "]" and state != "element":
            position += 1
            depth -= 1
            if depth == 0:
                if position != length:
                    return _invalid(position)
                return {"ok": True, "value": (values, max_depth)}
            state = "separator"
            continue

        if state == "separator":
            if char != ",":
                return _invalid(position)
            position += 1
            state = "element"
            continue

        if char == "[":
            position += 1
            depth += 1
            max_depth = max(max_depth, depth)
            state = "first"
            continue

        negative = char == "-"
        if negative:
            position += 1
        if position == length or not text[position].isdecimal():
            return _invalid(position)

        value = 0
        while position < length and text[position].isdecimal():
            value = value * 10 + int(text[position])
            position += 1

        values.append(-value if negative else value)
        state = "separator"

    return _invalid(length)

