from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

class Arrive(TypedDict):
    kind: Literal["Arrive"]
    plate: str
    minute: int

class Leave(TypedDict):
    kind: Literal["Leave"]
    plate: str
    minute: int

Park = Arrive | Leave


def parking_fees(events: list[Park]) -> list[tuple[str, int]]:
    parked: dict[str, int] = {}
    totals: dict[str, int] = {}

    for event in events:
        plate = event["plate"]
        minute = event["minute"]

        if event["kind"] == "Arrive":
            parked.setdefault(plate, minute)
            continue

        arrival = parked.pop(plate, None)
        if arrival is None:
            continue

        billable_minutes = max(0, minute - arrival - 30)
        started_hours = (billable_minutes + 59) // 60
        fee = min(1000, 200 * started_hours)
        totals[plate] = totals.get(plate, 0) + fee

    return sorted(totals.items())

