            output.append(stack.pop())
        elif kind in ("Add", "Sub", "Mul"):
            b = stack.pop()
            a = stack.pop()
            if kind == "Add":
                stack.append(a + b)
            elif kind == "Sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
        elif kind == "Halt":
            break

        pc += 1

