export function align_columns(rows: string[][]): string[] {
  const widths: number[] = [];

  for (const row of rows) {
    for (let j = 0; j < row.length; j++) {
      widths[j] = Math.max(widths[j] ?? 0, row[j].length);
    }
  }

  return rows.map((row) => {
    const line = row.map((cell, j) => cell.padEnd(widths[j], " ")).join(" | ");
    let end = line.length;
    while (end > 0 && line[end - 1] === " ") {
      end--;
    }
    return line.slice(0, end);
  });
}

