type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bracket_depth(s: string): Result<number> {
  const expected: string[] = [];
  let maxDepth = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];

    switch (ch) {
      case "(":
        expected.push(")");
        break;
      case "[":
        expected.push("]");
        break;
      case "{":
        expected.push("}");
        break;
      case ")":
      case "]":
      case "}":
        if (expected.pop() !== ch) {
          return { ok: false, error: `mismatch at ${i}` };
        }
        break;
      default:
        continue;
    }

    maxDepth = Math.max(maxDepth, expected.length);
  }

  if (expected.length > 0) {
    return { ok: false, error: "unclosed at end" };
  }

  return { ok: true, value: maxDepth };
}

