type BankOp =
  | { kind: "Open"; name: string }
  | { kind: "Deposit"; name: string; amount: number }
  | { kind: "Withdraw"; name: string; amount: number }
  | { kind: "Transfer"; src: string; dst: string; amount: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function bank_ledger(ops: BankOp[]): Result<([string, number])[]> {
  const balances = new Map<string, number>();

  for (const [index, op] of ops.entries()) {
    const fail = (message: string): { ok: false; error: string } => ({
      ok: false,
      error: `step ${index + 1}: ${message}`,
    });

    if (op.kind === "Open") {
      if (balances.has(op.name)) {
        return fail(`duplicate account ${op.name}`);
      }
      balances.set(op.name, 0);
      continue;
    }

    if (op.kind === "Transfer") {
      const srcBalance = balances.get(op.src);
      if (srcBalance === undefined) {
        return fail(`unknown account ${op.src}`);
      }
      const dstBalance = balances.get(op.dst);
      if (dstBalance === undefined) {
        return fail(`unknown account ${op.dst}`);
      }
      if (op.src === op.dst) {
        return fail("same account");
      }
      if (op.amount <= 0) {
        return fail("invalid amount");
      }
      if (op.amount > srcBalance) {
        return fail("insufficient funds");
      }
      balances.set(op.src, srcBalance - op.amount);
      balances.set(op.dst, dstBalance + op.amount);
      continue;
    }

    const balance = balances.get(op.name);
    if (balance === undefined) {
      return fail(`unknown account ${op.name}`);
    }
    if (op.amount <= 0) {
      return fail("invalid amount");
    }
    if (op.kind === "Withdraw") {
      if (op.amount > balance) {
        return fail("insufficient funds");
      }
      balances.set(op.name, balance - op.amount);
    } else {
      balances.set(op.name, balance + op.amount);
    }
  }

  return { ok: true, value: Array.from(balances) };
}

