function parseVersion(version: string): string[] | null {
  const parts = version.split(".");
  if (parts.length > 4 || parts.some(part => part === "" || /[^0-9]/.test(part))) {
    return null;
  }
  return parts.map(part => part.replace(/^0+/, ""));
}

export function compare_versions(a: string, b: string): Result<number> {
  const left = parseVersion(a);
  if (left === null) {
    return { ok: false, error: "bad version: " + a };
  }

  const right = parseVersion(b);
  if (right === null) {
    return { ok: false, error: "bad version: " + b };
  }

  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const x = left[i] ?? "";
    const y = right[i] ?? "";
    if (x.length !== y.length) {
      return { ok: true, value: x.length < y.length ? -1 : 1 };
    }
    if (x !== y) {
      return { ok: true, value: x < y ? -1 : 1 };
    }
  }

  return { ok: true, value: 0 };
}

