type Key = { kind: "Digit"; d: number } | { kind: "Enter" } | { kind: "Clear" };

export function door_lock(code: string, events: Key[]): string {
  let state: "locked" | "open" = "locked";
  let buffer = "";
  let failures = 0;

  for (const key of events) {
    if (state === "open") {
      if (key.kind === "Enter") {
        state = "locked";
      }
      continue;
    }

    switch (key.kind) {
      case "Digit":
        buffer = (buffer + String(key.d)).slice(-code.length);
        break;
      case "Clear":
        buffer = "";
        break;
      case "Enter": {
        const matches = buffer === code;
        buffer = "";

        if (matches) {
          state = "open";
          failures = 0;
        } else {
          failures += 1;
          if (failures === 3) {
            return "blocked";
          }
        }
        break;
      }
    }
  }

  return state;
}

