export function count_islands(grid: string[]): [number, number] {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  const visited = grid.map(() => new Uint8Array(width));
  const stack: [number, number][] = [];
  let islands = 0;
  let largest = 0;

  function visit(row: number, col: number): void {
    if (
      row >= 0 && row < height &&
      col >= 0 && col < width &&
      grid[row][col] === "#" &&
      visited[row][col] === 0
    ) {
      visited[row][col] = 1;
      stack.push([row, col]);
    }
  }

  for (let row = 0; row < height; row++) {
    for (let col = 0; col < width; col++) {
      visit(row, col);
      if (stack.length === 0) continue;

      islands++;
      let size = 0;
      for (let cell = stack.pop(); cell !== undefined; cell = stack.pop()) {
        const [r, c] = cell;
        size++;
        visit(r - 1, c);
        visit(r + 1, c);
        visit(r, c - 1);
        visit(r, c + 1);
      }
      largest = Math.max(largest, size);
    }
  }

  return [islands, largest];
}

