export function elevator_scan(
  start: number,
  requests: number[],
  direction: string,
): number[] {
  const above: number[] = [];
  const below: number[] = [];
  const result: number[] = [];

  for (const floor of new Set(requests)) {
    if (floor === start) {
      result.push(floor);
    } else if (floor > start) {
      above.push(floor);
    } else if (floor < start) {
      below.push(floor);
    }
  }

  above.sort((a, b) => a - b);
  below.sort((a, b) => b - a);

  return direction === "down"
    ? result.concat(below, above)
    : result.concat(above, below);
}

