type Job = { name: string; deps: string[] };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function build_order(jobs: Job[]): Result<string[]> {
  const indexByName = new Map<string, number>();
  for (const [index, job] of jobs.entries()) {
    if (indexByName.has(job.name)) {
      return { ok: false, error: "duplicate job: " + job.name };
    }
    indexByName.set(job.name, index);
  }

  const dependents: number[][] = jobs.map(() => []);
  const remaining = jobs.map(job => job.deps.length);
  for (const [index, job] of jobs.entries()) {
    for (const dep of job.deps) {
      const depIndex = indexByName.get(dep);
      if (depIndex === undefined) {
        return { ok: false, error: "unknown dependency: " + dep };
      }
      dependents[depIndex].push(index);
    }
  }

  // The min-heap keeps the earliest ready job at its root.
  const ready: number[] = [];

  function enqueue(index: number): void {
    let pos = ready.length;
    ready.push(index);
    while (pos > 0) {
      const parent = Math.floor((pos - 1) / 2);
      if (ready[parent] <= index) {
        break;
      }
      ready[pos] = ready[parent];
      pos = parent;
    }
    ready[pos] = index;
  }

  function dequeue(): number | undefined {
    const first = ready[0];
    const last = ready.pop();
    if (last === undefined || ready.length === 0) {
      return first;
    }

    let pos = 0;
    while (2 * pos + 1 < ready.length) {
      let child = 2 * pos + 1;
      const right = child + 1;
      if (right < ready.length && ready[right] < ready[child]) {
        child = right;
      }
      if (last <= ready[child]) {
        break;
      }
      ready[pos] = ready[child];
      pos = child;
    }
    ready[pos] = last;
    return first;
  }

  for (const [index, count] of remaining.entries()) {
    if (count === 0) {
      enqueue(index);
    }
  }

  const order: string[] = [];
  while (order.length < jobs.length) {
    const index = dequeue();
    if (index === undefined) {
      return { ok: false, error: "cycle detected" };
    }
    order.push(jobs[index].name);
    for (const dependent of dependents[index]) {
      remaining[dependent] -= 1;
      if (remaining[dependent] === 0) {
        enqueue(dependent);
      }
    }
  }

  return { ok: true, value: order };
}

