type Player = { name: string; score: number };

function compareNames(a: string, b: string): number {
  let i = 0;
  while (i < a.length && i < b.length) {
    const left = a.codePointAt(i)!;
    const right = b.codePointAt(i)!;
    if (left !== right) return left - right;
    i += left > 0xffff ? 2 : 1;
  }
  return a.length - b.length;
}

export function competition_rank(players: Player[]): ([number, string])[] {
  const sorted = [...players].sort((a, b) => {
    if (a.score > b.score) return -1;
    if (a.score < b.score) return 1;
    if (Number.isNaN(a.score) !== Number.isNaN(b.score)) {
      return Number.isNaN(a.score) ? 1 : -1;
    }
    return compareNames(a.name, b.name);
  });

  let rank = 1;
  return sorted.map(({ name, score }, index): [number, string] => {
    if (Number.isNaN(score)) return [1, name];
    if (index > 0 && score !== sorted[index - 1].score) {
      rank = index + 1;
    }
    return [rank, name];
  });
}

