export function heading_numbers(lines: string[]): string[] {
  const counters = [0, 0, 0];
  const output: string[] = [];

  for (const line of lines) {
    let level = 0;
    while (level < 3 && line[level] === "#") {
      level++;
    }

    if (level === 0 || line[level] !== " " || line.length <= level + 1) {
      continue;
    }

    counters[level - 1]++;
    counters.fill(0, level);

    const number = counters.slice(0, level).join(".");
    output.push(`${number} ${line.slice(level + 1)}`);
  }

  return output;
}

