type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function flatten_nested(s: string): Result<[number[], number]> {
  const text = s.replace(/ /g, "");
  const values: number[] = [];
  let i = 0;

  const invalid = (): Result<[number[], number]> => ({
    ok: false,
    error: `invalid at ${i}`,
  });

  const isDigit = (ch: string): boolean => ch >= "0" && ch <= "9";

  if (text.charAt(i) !== "[") return invalid();
  i++;

  let depth = 1;
  let maxDepth = 1;
  let state: "first" | "element" | "after" = "first";

  while (depth > 0) {
    const ch = text.charAt(i);

    if (ch === "]" && state !== "element") {
      i++;
      depth--;
      state = "after";
    } else if (state === "after") {
      if (ch !== ",") return invalid();
      i++;
      state = "element";
    } else if (ch === "[") {
      i++;
      depth++;
      maxDepth = Math.max(maxDepth, depth);
      state = "first";
    } else {
      const start = i;
      if (ch === "-") i++;
      if (!isDigit(text.charAt(i))) return invalid();
      do {
        i++;
      } while (isDigit(text.charAt(i)));
      values.push(Number(text.slice(start, i)));
      state = "after";
    }
  }

  if (i !== text.length) return invalid();
  return { ok: true, value: [values, maxDepth] };
}

