export function glob_match(pattern: string, s: string): boolean {
  const p = Array.from(pattern);
  const text = Array.from(s);
  let pi = 0;
  let si = 0;
  let afterStar = -1;
  let starEnd = 0;

  while (si < text.length) {
    const ch = p[pi];

    if (ch === "*") {
      afterStar = ++pi;
      starEnd = si;
      continue;
    }

    if (ch === "\\") {
      const escaped = pi + 1 < p.length;
      const literal = escaped ? p[pi + 1] : "\\";
      if (literal === text[si]) {
        pi += escaped ? 2 : 1;
        si++;
        continue;
      }
    } else if (ch === "?" || ch === text[si]) {
      pi++;
      si++;
      continue;
    }

    if (afterStar === -1) {
      return false;
    }

    // Give the most recent star one more character and retry its suffix.
    pi = afterStar;
    si = ++starEnd;
  }

  while (p[pi] === "*") {
    pi++;
  }

  return pi === p.length;
}

