type Stock = { sku: string; qty: number };
type Txn = { sku: string; delta: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function compareSkus(a: string, b: string): number {
  let i = 0;
  let j = 0;

  while (true) {
    const left = a.codePointAt(i);
    const right = b.codePointAt(j);

    if (left === undefined) return right === undefined ? 0 : -1;
    if (right === undefined) return 1;
    if (left !== right) return left - right;

    const width = left > 0xffff ? 2 : 1;
    i += width;
    j += width;
  }
}

export function inventory_ledger(stock: Stock[], txns: Txn[]): Result<Stock[]> {
  const quantities = new Map<string, number>();
  for (const { sku, qty } of stock) {
    quantities.set(sku, qty);
  }

  let position = 0;
  for (const { sku, delta } of txns) {
    position += 1;
    const current = quantities.get(sku);
    if (current === undefined) {
      return { ok: false, error: `txn ${position}: unknown sku ${sku}` };
    }

    const next = current + delta;
    if (next < 0) {
      return { ok: false, error: `txn ${position}: ${sku} would go negative` };
    }
    quantities.set(sku, next);
  }

  const value: Stock[] = [];
  for (const [sku, qty] of quantities) {
    if (qty > 0) {
      value.push({ sku, qty });
    }
  }
  value.sort((a, b) => compareSkus(a.sku, b.sku));
  return { ok: true, value };
}

