type Result<T> = { ok: true; value: T } | { ok: false; error: string };

type Operator = "+" | "-" | "*" | "/";

function precedence(op: Operator): number {
  return op === "*" || op === "/" ? 2 : 1;
}

export function eval_expr(s: string): Result<number> {
  const input = s.replaceAll(" ", "");
  const postfix: (string | Operator)[] = [];
  const operators: (Operator | "(")[] = [];
  let i = 0;
  let depth = 0;
  let needsFactor = true;

  function syntaxError(): Result<number> {
    const codePoint = input.codePointAt(i);
    return {
      ok: false,
      error: codePoint === undefined
        ? "unexpected end"
        : "unexpected character: " + String.fromCodePoint(codePoint),
    };
  }

  while (i < input.length) {
    const ch = input[i];
    if (needsFactor) {
      if (ch === "(") {
        operators.push(ch);
        depth++;
        i++;
      } else if (ch >= "0" && ch <= "9") {
        const start = i;
        do {
          i++;
        } while (i < input.length && input[i] >= "0" && input[i] <= "9");
        postfix.push(input.slice(start, i));
        needsFactor = false;
      } else {
        return syntaxError();
      }
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/") {
      let top = operators.at(-1);
      while (top !== undefined && top !== "(" && precedence(top) >= precedence(ch)) {
        postfix.push(top);
        operators.pop();
        top = operators.at(-1);
      }
      operators.push(ch);
      needsFactor = true;
      i++;
    } else if (ch === ")" && depth > 0) {
      let top = operators.pop();
      while (top !== undefined && top !== "(") {
        postfix.push(top);
        top = operators.pop();
      }
      depth--;
      i++;
    } else {
      return syntaxError();
    }
  }

  if (needsFactor || depth !== 0) {
    return syntaxError();
  }

  for (let op = operators.pop(); op !== undefined; op = operators.pop()) {
    postfix.push(op);
  }

  const values: bigint[] = [];
  for (const token of postfix) {
    if (token !== "+" && token !== "-" && token !== "*" && token !== "/") {
      values.push(BigInt(token));
      continue;
    }

    const right = values.pop()!;
    const left = values.pop()!;
    switch (token) {
      case "+":
        values.push(left + right);
        break;
      case "-":
        values.push(left - right);
        break;
      case "*":
        values.push(left * right);
        break;
      case "/":
        if (right === 0n) {
          return { ok: false, error: "division by zero" };
        }
        values.push(left / right);
        break;
    }
  }

  return { ok: true, value: Number(values[0]) };
}

