type Match = { home: string; away: string; home_goals: number; away_goals: number };

function compareNames(a: string, b: string): number {
  const right = b[Symbol.iterator]();
  for (const leftChar of a) {
    const next = right.next();
    if (next.done) return 1;
    const difference =
      (leftChar.codePointAt(0) ?? 0) - (next.value.codePointAt(0) ?? 0);
    if (difference !== 0) return difference;
  }
  return right.next().done ? 0 : -1;
}

export function league_table(matches: Match[]): ([string, number, number, number])[] {
  type Row = [string, number, number, number];
  const rows = new Map<string, Row>();

  function record(team: string, scored: number, conceded: number): void {
    let row = rows.get(team);
    if (row === undefined) {
      row = [team, 0, 0, 0];
      rows.set(team, row);
    }

    row[1] += scored > conceded ? 3 : scored === conceded ? 1 : 0;
    row[2] += scored - conceded;
    row[3] += scored;
  }

  for (const match of matches) {
    record(match.home, match.home_goals, match.away_goals);
    record(match.away, match.away_goals, match.home_goals);
  }

  return [...rows.values()].sort(
    (a, b) =>
      b[1] - a[1] ||
      b[2] - a[2] ||
      b[3] - a[3] ||
      compareNames(a[0], b[0]),
  );
}

