export function max_subarray(xs: number[]): [number, number, number] | null {
  if (xs.length === 0) {
    return null;
  }

  let sum = xs[0];
  let start = 0;
  let bestSum = sum;
  let bestStart = 0;
  let bestEnd = 0;

  for (let end = 1; end < xs.length; end++) {
    const value = xs[end];
    const extended = sum + value;

    if (value > extended) {
      sum = value;
      start = end;
    } else {
      sum = extended;
    }

    if (sum > bestSum || (sum === bestSum && start < bestStart)) {
      bestSum = sum;
      bestStart = start;
      bestEnd = end;
    }
  }

  return [bestSum, bestStart, bestEnd];
}

