type Contact = { name: string; email: string; phone: string };

export function merge_contacts(contacts: Contact[]): Contact[] {
  const parent = contacts.map((_, index) => index);
  const size = contacts.map(() => 1);

  function find(index: number): number {
    while (parent[index] !== index) {
      parent[index] = parent[parent[index]];
      index = parent[index];
    }
    return index;
  }

  function union(left: number, right: number): void {
    let a = find(left);
    let b = find(right);
    if (a === b) return;

    if (size[a] < size[b]) {
      [a, b] = [b, a];
    }
    parent[b] = a;
    size[a] += size[b];
  }

  function link(seen: Map<string, number>, key: string, index: number): void {
    if (key === "") return;

    const previous = seen.get(key);
    if (previous === undefined) {
      seen.set(key, index);
    } else {
      union(previous, index);
    }
  }

  const emails = new Map<string, number>();
  const phones = new Map<string, number>();

  for (const [index, contact] of contacts.entries()) {
    link(emails, contact.email.trim(), index);
    link(phones, contact.phone.replace(/[^0-9]/g, ""), index);
  }

  const mergedByRoot = new Map<number, Contact>();
  for (const [index, contact] of contacts.entries()) {
    const root = find(index);
    const merged = mergedByRoot.get(root);
    if (merged === undefined) {
      mergedByRoot.set(root, { ...contact });
    } else {
      if (merged.name === "") merged.name = contact.name;
      if (merged.email === "") merged.email = contact.email;
      if (merged.phone === "") merged.phone = contact.phone;
    }
  }

  return [...mergedByRoot.values()];
}

