type Park = { kind: "Arrive"; plate: string; minute: number } | { kind: "Leave"; plate: string; minute: number };

export function parking_fees(events: Park[]): ([string, number])[] {
  const parked = new Map<string, number>();
  const totals = new Map<string, number>();

  for (const { kind, plate, minute } of events) {
    if (kind === "Arrive") {
      if (!parked.has(plate)) {
        parked.set(plate, minute);
      }
      continue;
    }

    const arrival = parked.get(plate);
    if (arrival === undefined) {
      continue;
    }

    parked.delete(plate);
    const billableMinutes = Math.max(0, minute - arrival - 30);
    const fee = Math.min(1000, 200 * Math.ceil(billableMinutes / 60));
    totals.set(plate, (totals.get(plate) ?? 0) + fee);
  }

  return Array.from(totals).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
}

