export function parse_ipv4(s: string): Result<number> {
  const parts = s.split(".");
  if (parts.length !== 4) {
    return { ok: false, error: "expected 4 parts" };
  }

  let value = 0;
  for (const part of parts) {
    if (
      part.length === 0 ||
      part.length > 3 ||
      /[^0-9]/.test(part) ||
      (part.length > 1 && part.startsWith("0"))
    ) {
      return { ok: false, error: `bad part: ${part}` };
    }

    const octet = Number(part);
    if (octet > 255) {
      return { ok: false, error: `bad part: ${part}` };
    }

    value = value * 256 + octet;
  }

  return { ok: true, value };
}

