export function pig_latin(s: string): string {
  if (s === "") return "";

  return s.split(" ").map((word) => {
    for (let i = 0; i < word.length; i++) {
      const letter = word.charAt(i);
      const isVowel =
        "aeio".includes(letter) ||
        (letter === "u" && word.charAt(i - 1) !== "q") ||
        (letter === "y" && i > 0);

      if (isVowel) {
        return i === 0
          ? word + "way"
          : word.slice(i) + word.slice(0, i) + "ay";
      }
    }

    return word + "ay";
  }).join(" ");
}

