export function parse_money(s: string): Result<number> {
  const negative = s.startsWith("-");
  const dollarIndex = negative ? 1 : 0;

  if (s[dollarIndex] !== "$") {
    return { ok: false, error: "missing $" };
  }

  const dotIndex = s.indexOf(".");
  let cents = 0;
  if (dotIndex !== -1) {
    const text = s.slice(dotIndex + 1);
    if (text.length !== 2 || /[^0-9]/.test(text)) {
      return { ok: false, error: "bad cents" };
    }
    cents = Number(text);
  }

  const dollars = s.slice(dollarIndex + 1, dotIndex === -1 ? s.length : dotIndex);
  if (!/^(?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)$/.test(dollars)) {
    return { ok: false, error: "bad dollars" };
  }

  const amount = Number(dollars.replace(/,/g, "")) * 100 + cents;
  return { ok: true, value: negative ? -amount : amount };
}

