function compareDepartmentNames(a: string, b: string): number {
  let offset = 0;
  for (const char of a) {
    const bPoint = b.codePointAt(offset);
    if (bPoint === undefined) return 1;

    const aPoint = char.codePointAt(0)!;
    if (aPoint !== bPoint) return aPoint - bPoint;

    offset += char.length;
  }
  return offset === b.length ? 0 : -1;
}

