type Cmd = { kind: "Forward"; steps: number } | { kind: "TurnLeft" } | { kind: "TurnRight" };

export function robot_walk(cmds: Cmd[], obstacles: ([number, number])[]): [number, number, string] {
  const blocked = new Set(obstacles.map(([x, y]) => `${x},${y}`));
  const directions = ["N", "E", "S", "W"] as const;
  const offsets = [[0, 1], [1, 0], [0, -1], [-1, 0]] as const;
  let x = 0;
  let y = 0;
  let heading = 0;

  for (const cmd of cmds) {
    switch (cmd.kind) {
      case "TurnLeft":
        heading = (heading + 3) % 4;
        break;
      case "TurnRight":
        heading = (heading + 1) % 4;
        break;
      case "Forward": {
        const [dx, dy] = offsets[heading];
        for (let step = 1; step <= cmd.steps; step++) {
          const nextX = x + dx;
          const nextY = y + dy;
          if (blocked.has(`${nextX},${nextY}`)) {
            break;
          }
          x = nextX;
          y = nextY;
        }
        break;
      }
    }
  }

  return [x, y, directions[heading]];
}

