type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function symbolValue(symbol: string): number {
  switch (symbol) {
    case "I": return 1;
    case "V": return 5;
    case "X": return 10;
    case "L": return 50;
    case "C": return 100;
    case "D": return 500;
    case "M": return 1000;
    default: return 0;
  }
}

const standardPairs: ReadonlyArray<readonly [number, string]> = [
  [1000, "M"], [900, "CM"], [500, "D"], [400, "CD"],
  [100, "C"], [90, "XC"], [50, "L"], [40, "XL"],
  [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"],
];

export function roman_to_int(s: string): Result<number> {
  if (s === "") {
    return { ok: false, error: "empty" };
  }

  let total = 0;
  let previous = 0;
  for (const symbol of s) {
    const current = symbolValue(symbol);
    if (current === 0) {
      return { ok: false, error: `invalid character: ${symbol}` };
    }
    total += previous < current ? -previous : previous;
    previous = current;
  }
  total += previous;

  if (total < 1 || total > 3999) {
    return { ok: false, error: "not canonical" };
  }

  let remaining = total;
  let canonical = "";
  for (const [value, symbols] of standardPairs) {
    while (remaining >= value) {
      canonical += symbols;
      remaining -= value;
    }
  }

  if (s !== canonical) {
    return { ok: false, error: "not canonical" };
  }
  return { ok: true, value: total };
}

