type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function rle_decode(s: string): Result<string> {
  const groups: { character: string; count: number }[] = [];
  let current: { character: string; count: number } | undefined;

  for (const character of s) {
    if (character >= "0" && character <= "9") {
      if (current === undefined) {
        return { ok: false, error: "missing character before count" };
      }
      if (current.count === 0 && character === "0") {
        return { ok: false, error: `bad count for ${current.character}` };
      }
      current.count = current.count * 10 + Number(character);
    } else {
      current = { character, count: 0 };
      groups.push(current);
    }
  }

  const value = groups
    .map(({ character, count }) => character.repeat(count === 0 ? 1 : count))
    .join("");
  return { ok: true, value };
}

