  while (top <= bottom && left <= right) {
    for (let row = top; row <= bottom; row++) {
      result.push(m[row][left]);
    }
    left++;
    if (left > right) break;

    for (let col = left; col <= right; col++) {
      result.push(m[bottom][col]);
    }
    bottom--;
    if (top > bottom) break;

    for (let row = bottom; row >= top; row--) {
      result.push(m[row][right]);
    }
    right--;
    if (left > right) break;

    for (let col = right; col >= left; col--) {
      result.push(m[top][col]);
    }
    top++;
  }

  return result;
}

