export function settle_debts(expenses: Expense[], people: string[]): ([string, string, number])[] {
  const paid = new Map<string, bigint>();
  let total = 0n;

  for (const { payer, amount_cents } of expenses) {
    const amount = BigInt(amount_cents);
    paid.set(payer, (paid.get(payer) ?? 0n) + amount);
    total += amount;
  }

  const count = BigInt(people.length);
  const remainder = ((total % count) + count) % count;
  const share = (total - remainder) / count;
  const balances = people.map(
    (person, i) => (paid.get(person) ?? 0n) - share - (i < Number(remainder) ? 1n : 0n),
  );
  const payments: [string, string, number][] = [];

