export function tennis_score(points: string): string {
  const names = ["love", "15", "30", "40"];
  let a = 0;
  let b = 0;
  let winner: "A" | "B" | null = null;

  for (const point of points) {
    if (winner !== null) return "error: point after game";

    if (point === "A") {
      a++;
    } else if (point === "B") {
      b++;
    } else {
      return "error: bad point";
    }

    if (a >= 4 && a - b >= 2) winner = "A";
    if (b >= 4 && b - a >= 2) winner = "B";
  }

  if (winner !== null) return `game ${winner}`;
  if (a >= 3 && b >= 3) {
    return a === b ? "deuce" : `advantage ${a > b ? "A" : "B"}`;
  }

  return a === b ? `${names[a]}-all` : `${names[a]}-${names[b]}`;
}

