type State = {
  remaining: bigint;
  coin: number;
  parent: State | null;
};

export function min_coins(coins: number[], amount: number): [number, number[]] | null {
  if (amount === 0) return [0, []];
  if (amount < 0 || !Number.isFinite(amount)) return null;

  const values = [...new Set(coins.filter((coin) => coin > 0 && coin <= amount))]
    .sort((a, b) => b - a);
  if (values.length === 0) return null;

  // Express each positive number exactly in units of 2^-1074.
  const view = new DataView(new ArrayBuffer(8));
  const hiddenBit = 1n << 52n;
  function units(value: number): bigint {
    view.setFloat64(0, value);
    const bits = view.getBigUint64(0);
    const exponent = Number(bits >> 52n);
    const fraction = bits & (hiddenBit - 1n);
    return exponent === 0
      ? fraction
      : (hiddenBit | fraction) << BigInt(exponent - 1);
  }

  const choices = values.map((value) => ({ value, cost: units(value) }));
  const target = units(amount);

  let divisor = 0n;
  for (const { cost } of choices) {
    let rest = cost;
    while (rest !== 0n) {
      const remainder = divisor % rest;
      divisor = rest;
      rest = remainder;
    }
  }
  if (target % divisor !== 0n) return null;

  const start = target / divisor;
  for (const choice of choices) choice.cost /= divisor;

  const queue: State[] = [{ remaining: start, coin: 0, parent: null }];
  const seen = new Set<bigint>([start]);

  for (let i = 0; i < queue.length; i++) {
    const state = queue[i];
    for (const { value, cost } of choices) {
      const remaining = state.remaining - cost;
      if (remaining < 0n || seen.has(remaining)) continue;

      if (remaining === 0n) {
        const used = [value];
        let step = state;
        while (step.parent !== null) {
          used.push(step.coin);
          step = step.parent;
        }
        return [used.length, used.reverse()];
      }

      seen.add(remaining);
      queue.push({ remaining, coin: value, parent: state });
    }
  }

  return null;
}

