      cells[a] === mark && cells[b] === mark && cells[c] === mark
    );

  const xWins = hasLine("X");
  const oWins = hasLine("O");

  if (
    (xWins && oWins) ||
    (xWins && difference !== 1) ||
    (oWins && difference !== 0)
  ) {
    return "invalid";
  }

  if (xWins) {
    return "X wins";
  }
  if (oWins) {
    return "O wins";
  }
  return cells.includes(".") ? "in progress" : "draw";
}

