  | { kind: "Dup" }
  | { kind: "Swap" }
  | { kind: "Jz"; target: number }
  | { kind: "Jmp"; target: number }
  | { kind: "Print" }
  | { kind: "Halt" };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function stack_vm(prog: Instr[]): Result<number[]> {
  const stack: number[] = [];
  const output: number[] = [];
  let pc = 0;
  let steps = 0;

  while (pc < prog.length) {
    if (steps === 1000) {
      return { ok: false, error: "step limit exceeded" };
    }
    steps += 1;

    const instr = prog[pc];
    const kind = instr.kind;
    const needed =
      kind === "Add" || kind === "Sub" || kind === "Mul" || kind === "Swap"
        ? 2
        : kind === "Pop" || kind === "Dup" || kind === "Print" || kind === "Jz"
          ? 1
          : 0;

    if (stack.length < needed) {
      return { ok: false, error: `stack underflow at ${pc}` };
    }

    if (
      (kind === "Jz" || kind === "Jmp") &&
      (!Number.isInteger(instr.target) ||
        instr.target < 0 ||
        instr.target >= prog.length)
    ) {
      return { ok: false, error: `bad jump at ${pc}` };
    }

    switch (kind) {
      case "Push":
        stack.push(instr.n);
        break;
      case "Pop":
        stack.pop();
        break;
      case "Add":
      case "Sub":
      case "Mul":
      case "Swap": {
        const b = stack[stack.length - 1];
        const a = stack[stack.length - 2];
        stack.length -= 2;
        if (kind === "Swap") {
          stack.push(b, a);
        } else {
          stack.push(kind === "Add" ? a + b : kind === "Sub" ? a - b : a * b);
        }
        break;
      }
      case "Dup":
        stack.push(stack[stack.length - 1]);
        break;
      case "Jz":
        if (stack.pop() === 0) {
          pc = instr.target;
          continue;
        }
        break;
      case "Jmp":
        pc = instr.target;
        continue;
      case "Print":
        output.push(stack[stack.length - 1]);
        stack.pop();
        break;
      case "Halt":
        return { ok: true, value: output };
    }

    pc += 1;
  }

  return { ok: true, value: output };
}

