type Student = { name: string; scores: number[] };

function compareNames(a: string, b: string): number {
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    const left = a.codePointAt(i)!;
    const right = b.codePointAt(j)!;
    if (left !== right) return left - right;

    i += left > 0xffff ? 2 : 1;
    j += right > 0xffff ? 2 : 1;
  }

  return (a.length - i) - (b.length - j);
}

export function student_medians(students: Student[]): ([string, number])[] {
  const medians: [string, number][] = [];

  for (const { name, scores } of students) {
    if (scores.length === 0) continue;

    const sorted = [...scores].sort((a, b) => a - b);
    const middle = Math.floor(sorted.length / 2);
    const upper = sorted[middle];
    let median = upper;

    if (sorted.length % 2 === 0) {
      const lower = sorted[middle - 1];
      const sum = lower + upper;
      median = Number.isFinite(sum) ? sum / 2 : lower / 2 + upper / 2;
    }

    medians.push([name, median]);
  }

  return medians.sort(
    ([nameA, medianA], [nameB, medianB]) =>
      (medianB - medianA) || compareNames(nameA, nameB),
  );
}

