export function wrap_text(s: string, width: number): string[] {
  const lines: string[] = [];
  let line = "";

  for (const word of s.split(/ +/)) {
    if (word === "") {
      continue;
    }

    if (line === "") {
      line = word;
    } else if (line.length + 1 + word.length <= width) {
      line += " " + word;
    } else {
      lines.push(line);
      line = word;
    }
  }

  if (line !== "") {
    lines.push(line);
  }

  return lines;
}

