export function vending_machine(events: Event[]): string[] {
  let credit = 0;
  const messages: string[] = [];

  for (const event of events) {
    switch (event.kind) {
      case "Coin": {
        const cents = event.cents;
        if (cents === 5 || cents === 10 || cents === 25 || cents === 100) {
          credit += cents;
        } else {
          messages.push(`reject ${cents}`);
        }
        break;
      }
      case "Select": {
        const price = event.price;
        if (credit >= price) {
          messages.push(`vend ${price} change ${credit - price}`);
          credit = 0;
        } else {
          messages.push(`insufficient ${credit}`);
        }
        break;
      }
      case "Refund":
        if (credit > 0) {
          messages.push(`refund ${credit}`);
          credit = 0;
        }
        break;
    }
  }

  if (credit > 0) {
    messages.push(`refund ${credit}`);
  }

  return messages;
}

