type Token =
  | { kind: "Num"; value: number }
  | { kind: "Ident"; name: string }
  | { kind: "Sym"; text: string };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function isDigit(c: string): boolean {
  return c >= "0" && c <= "9";
}

function isIdentStart(c: string): boolean {
  return c === "_" || (c >= "a" && c <= "z");
}

export function tokenize(s: string): Result<Token[]> {
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    const c = s.charAt(i);

    if (c === " ") {
      i += 1;
    } else if (isDigit(c)) {
      const start = i;
      do {
        i += 1;
      } while (isDigit(s.charAt(i)));
      tokens.push({ kind: "Num", value: Number(s.slice(start, i)) });
    } else if (isIdentStart(c)) {
      const start = i;
      let next: string;
      do {
        i += 1;
        next = s.charAt(i);
      } while (isIdentStart(next) || isDigit(next));
      tokens.push({ kind: "Ident", name: s.slice(start, i) });
    } else {
      const pair = s.slice(i, i + 2);
      if (pair === "==" || pair === "<=" || pair === ">=" || pair === "!=") {
        tokens.push({ kind: "Sym", text: pair });
        i += 2;
      } else if ("+-*/=<>() ,".includes(c)) {
        tokens.push({ kind: "Sym", text: c });
        i += 1;
      } else {
        return { ok: false, error: `unexpected character: ${c} at ${i}` };
      }
    }
  }

  return { ok: true, value: tokens };
}

