    products.set(product, (products.get(product) ?? 0) + units * price_cents);
  }

  const result: [string, string, number][] = [];
  for (const [region, products] of totals) {
    let best: [string, string, number] | undefined;
    for (const [product, revenue] of products) {
      if (
        best === undefined ||
        revenue > best[2] ||
        (revenue === best[2] && compareCodePoints(product, best[1]) < 0)
      ) {
        best = [region, product, revenue];
      }
    }
    if (best !== undefined) result.push(best);
  }

  return result.sort((a, b) => compareCodePoints(a[0], b[0]));
}

final:
type Sale = { region: string; product: string; units: number; price_cents: number };

function compareCodePoints(a: string, b: string): number {
  let i = 0;
  while (i < a.length && i < b.length) {
    const left = a.codePointAt(i) ?? 0;
    const right = b.codePointAt(i) ?? 0;
    if (left !== right) return left - right;
    i += left > 0xffff ? 2 : 1;
  }
  return a.length - b.length;
}

export function top_product_per_region(sales: Sale[]): ([string, string, number])[] {
  const totals = new Map<string, Map<string, number>>();

  for (const { region, product, units, price_cents } of sales) {
    let products = totals.get(region);
    if (products === undefined) {
      products = new Map<string, number>();
      totals.set(region, products);
    }
    products.set(product, (products.get(product) ?? 0) + units * price_cents);
  }

  const result: [string, string, number][] = [];
  for (const [region, products] of totals) {
    let best: [string, string, number] | undefined;
    for (const [product, revenue] of products) {
      if (
        best === undefined ||
        revenue > best[2] ||
        (revenue === best[2] && compareCodePoints(product, best[1]) < 0)
      ) {
        best = [region, product, revenue];
      }
    }
    if (best !== undefined) result.push(best);
  }

  return result.sort((a, b) => compareCodePoints(a[0], b[0]));
}
